window.MATLAB_CODE={"chapters":[{"id":"ch1","name":"第一章","files":[{"name":"chase.m","page":null,"code":"function [x] = chase(A,d)\nb=[0;diag(tril(A,-1),-1)];%下对角线  tril(A,-1)仅提取主对角线下方的元素。\na=diag(A);%中对角线\nc=[diag(triu(A,1),1);0];%上对角线\nl=zeros(size(b,1),1);%求L size(a,1)仅查询 a 的第1个维度的长度\nu=zeros(size(a,1),1);%求U\nn=size(a,1);%矩阵的维度\nx=zeros(n,1);\ny=zeros(n,1);\nu(1)=a(1);\nfor i=2:n\n    l(i)=b(i)/u(i-1);\n    u(i)=a(i)-l(i)*c(i-1);\nend\ny(1)=d(1);\nfor i=2:n\n    y(i)=d(i)-l(i)*y(i-1);\nend\nx(n)=y(n)/u(n);\nfor i=n-1:-1:1\n    x(i)=(y(i)-c(i)*x(i+1))/u(i);\nend\nend"},{"name":"f.m","page":null,"code":"function E_max=f(m,n,x_1,x_2,t_1,t_2,a,s)\nformat long e\n  m=input('m=');\n  n=input('n=');\n  x_1=1;\n  x_2=2;\n   s=0.1;\n  a=2;\n  t_1=0;\n  t_2=1;\n h_1=(x_2-x_1)/m;\n h_2=s/n;\n r=a*h_2/(h_1^2);\n N=floor(t_2/h_2);\n x=(x_1+(0:m)*h_1)';\n t=(0+(-n:N)*h_2)';\n u=zeros(length(t),length(x));\n v=zeros(length(t),length(x));\n b=zeros(m-1,1);\n G=@(x,t) 3*(t^2)*(x^4-5*x)-24*(x^2)*(t^3+6)-(x^4-5*x)^2*((t-0.1)^3+6)^2-(x^4-5*x)^3*((t-0.1)^3+6)^3;\n \n \n for i=1:N\n     u(i,1)=-4*(t(length(t)-i+1)^3+6);\n     u(i,length(x))=6*(t(length(t)-i+1)^3+6);\n end\n for i=N+1:length(t)\n     for j=1:length(x)\n        u(i,j)=(x(j)^4-5*x(j))*(t(length(t)-i+1)^3+6);\n     end\n end\n \n A=diag(((55/36)+2*r)*linspace(1,1,m-1))+diag(((11/72)-r)*linspace(1,1,m-2),-1)+diag(((11/72)-r)*linspace(1,1,m-2),1);\n B=diag((5/2)*linspace(1,1,m-1))+diag((1/4)*linspace(1,1,m-2),-1)+diag((1/4)*linspace(1,1,m-2),1);\n C=diag((-5/4)*linspace(1,1,m-1))+diag((-1/8)*linspace(1,1,m-2),-1)+diag((-1/8)*linspace(1,1,m-2),1);\n D=diag((5/18)*linspace(1,1,m-1))+diag((1/36)*linspace(1,1,m-2),-1)+diag((1/36)*linspace(1,1,m-2),1);\n\n \n for i=1:length(t)\n     for j=1:length(x)\n         v(i,j)=(x(j)^4-5*x(j))*(t(length(t)-i+1)^3+6);\n     end\n end\nu(N,2:length(x)-1)=v(N,2:length(x)-1);\nu(N-1,2:length(x)-1)=v(N-1,2:length(x)-1);\n\n\nfor k=N-2:-1:1\n    for i=2:m-2\n       b(1)=-(11/72-r)*u(k,1)+(1/4)*u(k+1,1)+(-1/8)*u(k+2,1)+(1/36)*u(k+3,1)+  h_2*((1/12)*(u(k+n,1)^2+u(k+n,1)^3+G(x(1),t(length(t)-k+1)))+(10/12)*(u(k+n,2)^2+u(k+n,2)^3+G(x(2),t(length(t)-k+1)))+(1/12)*(u(k+n,3)^2+u(k+n,3)^3+G(x(3),t(length(t)-k+1))));\n       b(m-1)=-(11/72-r)*u(k,length(x))+(1/4)*u(k+1,length(x))+(-1/8)*u(k+2,length(x))+(1/36)*u(k+3,length(x))+  h_2*((1/12)*(u(k+n,m-1)^2+u(k+n,m-1)^3+G(x(m-1),t(length(t)-k+1)))+(10/12)*(u(k+n,m)^2+u(k+n,m)^3+G(x(m),t(length(t)-k+1)))+(1/12)*(u(k+n,m+1)^2+u(k+n,m+1)^3+G(x(m+1),t(length(t)-k+1))));\n       b(i)=h_2*((1/12)*(u(k+n,i)^2+u(k+n,i)^3+G(x(i),t(length(t)-k+1)))+(10/12)*(u(k+n,i+1)^2+u(k+n,i+1)^3+G(x(i+1),t(length(t)-k+1)))+(1/12)*(u(k+n,i+2)^2+u(k+n,i+2)^3+G(x(i+2),t(length(t)-k+1))));\n    end\n    u(k,2:length(x)-1)=chase(A,(B*u(k+1,2:length(x)-1)'+C*u(k+2,2:length(x)-1)'+D*u(k+3,2:length(x)-1)'+b));             \nend\n\n\n for i=1:length(t)\n     for j=1:length(x)\n         v(i,j)=(x(j)^4-5*x(j))*(t(length(t)-i+1)^3+6);\n     end\n end\n abs(u-v);\n E_max=max(max(abs(u-v)));"},{"name":"F1.m","page":null,"code":"function y = F1(x)\ny = exp(x).*(sin(x)-2*cos(x));"},{"name":"Maxerr.m","page":null,"code":"function [u,F,MaxErr]=Maxerr(M)\nxa=0;xb=pi;\nh=(xb-xa)/M;\nx=xa:h:xb;x=x';\nu=zeros(M+1,1);\nu(1,1)=0;\nu(M+1,1)=0;\nrow1=zeros(M-1,1);\nrow1(1,1)=2+h^2;row1(2,1)=-1;\nA=toeplitz(row1);\nH=zeros(M-1,1);\nH(1) = h^2*F1(x(2));\nH(M-1) = h^2*F1(x(M));\nH(2:M-2,1) = h^2*F1(x(3:M-1));\nu(2:M,1)=A\\H;\nF=exp(x).*sin(x); \nerror=abs(u-F);\nMaxErr = max((error()));"},{"name":"page14.m","page":14,"code":"for ii=1:5\nM=10*(2^(ii-1));\nxa=0;xb=pi;\nh=(xb-xa)/M;\nx=xa:h:xb;x=x';\nu=zeros(M+1,1);\nu(1,1)=0;\nu(M+1,1)=0;\nrow1=zeros(M-1,1);\nrow1(1,1)=2+h^2;row1(2,1)=-1;\nA=toeplitz(row1);\nH=zeros(M-1,1);\nH(1) = h^2*F1(x(2));\nH(M-1) = h^2*F1(x(M));\nH(2:M-2,1) = h^2*F1(x(3:M-1));\nu(2:M,1)=A\\H;\nF=zeros(M,1);\nfor j=1:M+1\n    F(j)=exp(x(j))*sin(x(j));\nend\nerror=abs(u-F);\nMaxErr(ii) = max((error()));\ndisp(['最大误差: ', num2str(MaxErr(ii))]);\nfigure(1)\nplot(x,u,'o--')\nhold on\nfigure(2)\nplot(x,error,'--')\nhold on\nend\nfor j=2:5\n    ord=MaxErr(j-1)/MaxErr(j);\n    disp(ord)\nend\n\n"},{"name":"page14chase.m","page":14,"code":"for ii=1:5\nM=10*(2^(ii-1));\nxa=0;xb=pi;\nh=(xb-xa)/M;\nx=xa:h:xb;x=x';\nu=zeros(M+1,1);\nu(1,1)=0;\nu(M+1,1)=0;\nrow1=zeros(M-1,1);\nrow1(1,1)=2+h^2;row1(2,1)=-1;\nA=toeplitz(row1);\nH=zeros(M-1,1);\nH(1) = h^2*F1(x(2));\nH(M-1) = h^2*F1(x(M));\nH(2:M-2,1) = h^2*F1(x(3:M-1));\nu(2:M,1)=chase(A,H);\nF=zeros(M,1);\nfor j=1:M+1\n    F(j)=exp(x(j))*sin(x(j));\nend\nerror=abs(u-F);\nMaxErr(ii) = max((error()));\ndisp(['最大误差: ', num2str(MaxErr(ii))]);\nfigure(1)\nplot(x,u,'o--')\nhold on\nfigure(2)\nplot(x,error,'--')\nhold on\nend\nfor j=2:5\n    ord=MaxErr(j-1)/MaxErr(j);\n    disp(ord)\nend\n\n"},{"name":"page29.m","page":29,"code":"N = 6;\nM = 10; \nfor i =1:N\n  [u1,F1,MaxErr1] = Maxerr(2^(i-1)*M);\n    [u2,F2,MaxErr2] = Maxerr(2^i*M);\n    Err(i)=max(abs(F1-(4*u2(1:2:(2^i*M)+1)-u1)/3));\nend\nOrd = Err(1:N-1)./Err(2:N);"},{"name":"page30.m","page":30,"code":"for ii=1:11\nM=10*(2^(ii-1));\nxa=0;xb=pi;\nh=(xb-xa)/M;\nx=xa:h:xb;x=x';\nu=zeros(M+1,1);\nu(1,1)=0;\nu(M+1,1)=0;\nrow1=zeros(M-1,1);\nrow1(1,1)=5/6+2/(h^2);row1(2,1)=1/12-1/(h^2);\nA=toeplitz(row1);\nH=zeros(M-1,1);\nH(1) = (5/6)*F1(x(2))+(1/12)*F1(x(1))+(1/12)*F1(x(3));\nH(M-1) =  (5/6)*F1(x(M))+(1/12)*F1(x(M-1))+(1/12)*F1(x(M+1));\nH(2:M-2,1) = (5/6)*F1(x(3:M-1))+(1/12)*F1(x(3:M-1))+(1/12)*F1(x(3:M-1));\nu(2:M,1)=A\\(H);\nF=zeros(M,1);\nfor j=1:M+1\n    F(j)=exp(x(j))*sin(x(j));\nend\nerror=abs(u-F);\nMaxErr(ii) = max((error()));\ndisp(['最大误差: ', num2str(MaxErr(ii))]);\nfigure(1)\nplot(x,u,'o--')\nhold on\nfigure(2)\nplot(x,error,'--')\nhold on\nend\nfor j=2:10\n    ord=MaxErr(j-1)/MaxErr(j+1);\n    disp(ord)\nend"},{"name":"page36.m","page":36,"code":"for ii=5:8\nM=10*(2^(ii-1));\nxa=0;xb=pi;\nh=(xb-xa)/M;\nx=xa:h:xb;x=x';\nu=zeros(M+1,1);\nF1 =@(x) exp(x).*(sin(x)-2*cos(x));\nrow1=zeros(M+1,1);\n\nrow1(1,1)=2+h^2;row1(2,1)=-1;\nA=toeplitz(row1);\nH=zeros(M+1,1);\nH(1) = 0;\nH(M+1) = 0;\nH(2:M,1) = h^2*F1(x(2:M));\nu=A\\H;\nF=zeros(M,1);\nfor j=1:M+1\n    F(j)=exp(x(j))*sin(x(j));\nend\nerror=abs(u-F);\nMaxErr(ii) = max((error));\ndisp(['最大误差: ', num2str(MaxErr(ii))]);\nfigure(1)\nplot(x,u,'^')\nhold on\nfigure(2)\nplot(x,error,'--')\nhold on\nend\nfor j=5:7\n    ord=MaxErr(j)/MaxErr(j+1);\n    disp(ord)\nend"},{"name":"page38.m","page":38,"code":"for ii=1:5\nM=10*(2^(ii-1));\nxa=0;xb=pi;\nh=(xb-xa)/M;\nx=xa:h:xb;x=x';\nu=zeros(M+1,1);\nA=zeros(M+1,M+1);\nrow1=zeros(M+1,1);\nrow1(1,1)=2+h^2;row1(2,1)=-1;\nA=toeplitz(row1);\nA(1,1)=1+(3*h^2)/2;\nA(M+1,M+1)=1+(3*h^2)/2;\nH=zeros(M+1,1);\nH(1,1) = -h*(1+h);\nH(2:M,1) = h^2*F1(x(2:M));\nH(M+1,1) = h*(h-1)*exp(pi);\nu=A\\H;\nF=zeros(M,1);\nfor j=1:M+1\n    F(j)=exp(x(j))*sin(x(j));\nend\nerror=abs(u-F);\nMaxErr(ii) = max((error()));\ndisp(['最大误差: ', num2str(MaxErr(ii))]);\nfigure(1)\nplot(x,u,'o')\nhold on\nfigure(2)\nplot(x,error,'-')\nhold on\nend\nfor j=2:5\n    ord=MaxErr(j-1)/MaxErr(j);\n    disp(ord)\nend"},{"name":"untitled.m","page":null,"code":"clc;\nt=0:0.001:0.6;%设置步进与时间区间\nx=sin(2*pi*50*t)+sin(2*pi*120*t);%根据已知写出信号的表达式\nnoise=randn(1,length(t));%生成均值为零、方差为1的随机信号，也就是噪声\ny=x+noise;%带有噪声的信号\nsubplot(121);\nplot(t,y);\n\nfs=1000;\nY=fft(y,512);%512点的FFT\nP=Y.*conj(Y)/512;%求功率\nf=(0:255)*fs/256%由上面的分析可知，频谱关于奈奎斯特频率对称，所以取其中一半\nsubplot(122);\nplot(f,P(1:256))%功率随频率的变化，即功率谱图,绘制出一半\n"},{"name":"untitled2.m","page":null,"code":"% 空间和时间离散参数\nL = 10; % 空间区间长度\nT = 5; % 总时间\nnx_vec = [50, 100, 200, 400]; % 不同的空间网格点数向量，用于收敛阶分析\nnt_vec = [250, 500, 1000, 2000]; % 不同的时间步数向量，用于收敛阶分析\nc = 1; % 波速\n\n% 用于存储不同离散尺度下的误差（用于收敛阶计算）\nerrors_nx = zeros(length(nx_vec), 1);\nerrors_nt = zeros(length(nt_vec), 1);\n\n% 循环计算不同空间离散尺度下的解和误差\nfor i = 1:length(nx_vec)\n    nx = nx_vec(i);\n    dx = L / (nx - 1);\n    nt = 1000; % 固定时间步数（可以根据情况调整，这里保证时间足够精确来主要分析空间离散影响）\n    dt = T / nt;\n    \n    % 初始化空间网格和初始条件\n    x = linspace(0, L, nx)';\n    u = zeros(nx, nt);\n    u(:, 1) = exp(-(x - 5).^2); % 初始位移分布\n    \n    % 构造二阶中心差分格式的系数矩阵用于空间二阶导数\n    e = ones(nx, 1);\n    A = spdiags([e -2*e e], [-1 0 1], nx, nx) / dx^2;\n    \n    % 时间推进循环\n    for n = 2:nt\n        % 对当前时间步的位移进行FFT\n        U_hat = fft(u(:, n - 1));\n        % 应用波动方程在频域的解（考虑到边界条件等）\n        omega = (2 * pi / L) * [0:(nx / 2 - 1) (-nx / 2):-1]'; % 波数向量\n        factor = -c^2 * omega.^2 * dt^2;\n        U_hat = (1 + factor / 2)./(1 - factor / 2).* U_hat;\n        % 进行逆FFT回到空间域得到下一个时间步的位移\n        u(:, n) = real(ifft(U_hat));\n    end\n    \n    % 计算精确解\n    t = (0:nt - 1)' * dt;\n    u_exact = cos(2 * pi * (x - c * t));\n    % 计算误差（这里用L2范数误差为例）\n    errors_nx(i) = sqrt(sum(sum((u - u_exact).^2)) / (nx * nt));\nend\n\n% 循环计算不同时间离散尺度下的解和误差\nfor i = 1:length(nt_vec)\n    nt = nt_vec(i);\n    dt = T / nt;\n    nx = 200; % 固定空间网格点数（可以根据情况调整，这里保证空间足够精确来主要分析时间离散影响）\n    dx = L / (nx - 1);\n    \n    % 初始化空间网格和初始条件\n    x = linspace(0, L, nx)';\n    u = zeros(nx, nt);\n    u(:, 1) = exp(-(x - 5).^2); % 初始位移分布\n    \n    % 构造二阶中心差分格式的系数矩阵用于空间二阶导数\n    e = ones(nx, 1);\n    A = spdiags([e -2*e e], [-1 0 1], nx, nx) / dx^2;\n    \n    % 时间推进循环\n    for n = 2:nt\n        % 对当前时间步的位移进行FFT\n        U_hat = fft(u(:, n - 1));\n        % 应用波动方程在频域的解（考虑到边界条件等）\n        omega = (2 * pi / L) * [0:(nx / 2 - 1) (-nx / 2):-1]'; % 波数向量\n        factor = -c^2 * omega.^2 * dt^2;\n        U_hat = (1 + factor / 2)./(1 - factor / 2).* U_hat;\n        % 进行逆FFT回到空间域得到下一个时间步的位移\n        u(:, n) = real(ifft(U_hat));\n    end\n    \n    % 计算精确解\n    t = (0:nt - 1)' * dt;\n    u_exact = cos(2 * pi * (x - c * t));\n    % 计算误差（这里用L2范数误差为例）\n    errors_nt(i) = sqrt(sum(sum((u - u_exact).^2)) / (nx * nt));\nend\n\n% 绘制数值解收敛阶曲线（空间离散）\nloglog(nx_vec, errors_nx, 'o-', 'LineWidth', 1.5);\nhold on;\np = polyfit(log(nx_vec), log(errors_nx), 1); % 拟合直线求斜率（收敛阶）\nloglog(nx_vec, exp(polyval(p, log(nx_vec))), 'r--', 'LineWidth', 1.5);\ntitle('Convergence Order (Spatial Discretization)');\nxlabel('Number of Spatial Grid Points (nx)');\nylabel('Error (L2 Norm)');\nlegend('Numerical Error', 'Fitted Order');\nhold off;\n\n% 绘制数值解收敛阶曲线（时间离散）\nfigure;\nloglog(nt_vec, errors_nt, 'o-', 'LineWidth', 1.5);\nhold on;\np = polyfit(log(nt_vec), log(errors_nt), 1); % 拟合直线求斜率（收敛阶）\nloglog(nt_vec, exp(polyval(p, log(nt_vec))), 'r--', 'LineWidth', 1.5);\ntitle('Convergence Order (Temporal Discretization)');\nxlabel('Number of Time Steps (nt)');\nylabel('Error (L2 Norm)');\nlegend('Numerical Error', 'Fitted Order');\nhold off;\n\n% 重新计算一个固定离散尺度下的误差曲面（以nx=100, nt=500为例）\nnx = 100;\nnt = 500;\ndx = L / (nx - 1);\ndt = T / nt;\nx = linspace(0, L, nx)';\nu = zeros(nx, nt);\nu(:, 1) = exp(-(x - 5).^2); % 初始位移分布\n% 构造二阶中心差分格式的系数矩阵用于空间二阶导数\ne = ones(nx, 1);\nA = spdiags([e -2*e e], [-1 0 1], nx, nx) / dx^2;\nfor n = 2:nt\n    % 对当前时间步的位移进行FFT\n    U_hat = fft(u(:, n - 1));\n    % 应用波动方程在频域的解（考虑到边界条件等）\n    omega = (2 * pi / L) * [0:(nx / 2 - 1) (-nx / 2):-1]'; % 波数向量\n    factor = -c^2 * omega.^2 * dt^2;\n    U_hat = (1 + factor / 2)./(1 - factor / 2).* U_hat;\n    % 进行逆FFT回到空间域得到下一个时间步的位移\n    u(:, n) = real(ifft(U_hat));\nend\nt = (0:nt - 1)' * dt;\nu_exact = cos(2 * pi * (x - c * t));\nerrors = (u - u_exact).^2; % 误差矩阵\n\n% 绘制误差曲面\nfigure;\n[X, T] = meshgrid(x, t);\nsurf(X, T, errors);\ntitle('Error Surface');\nxlabel('x');\nylabel('t');\nzlabel('Error');"}],"topics":[{"name":"三对角方程与追赶法","desc":"用追赶法（Thomas 算法）解三对角线性方程组，并作为一维差分方程的快速求解器。","files":["chase.m","page14chase.m"]},{"name":"一维边值问题的差分法","desc":"对两点边值问题作二阶中心差分离散，比较不同网格数下的最大误差与收敛阶。","files":["f.m","F1.m","Maxerr.m","page14.m","page29.m","page30.m","page36.m","page38.m"]},{"name":"拓展实验","desc":"信号去噪与一维/二维问题的收敛性试验，属于课程外的拓展代码。","files":["untitled.m","untitled2.m"]}]},{"id":"ch2","name":"第二章","files":[{"name":"example1.m","page":null,"code":"A=[1 1 1 1 1;\n   2 1 0 -1 -2;\n   2 1/2 0 1/2 2;\n   4/3 1/6 0 -1/6 4/3;\n   4/15 1/120 0 -1/120 -4/15];\nb=[0 0 1 0 0];\nb=b';\nx=A\\b;\ndisp(x);"},{"name":"F2.m","page":null,"code":"function z=F2(x,y)\nz=((pi)^2-1)*exp(x)*sin(pi*y);\nend"},{"name":"page53.m","page":53,"code":"MaxErr=zeros(4,1);\nfor i=1:4\n    xa=0;xb=2;ya=0;yb=1;\n    m=4*2^i;\n    n=4*2^i;\nh1=(xb-xa)/m;\nh2=(yb-ya)/n;\nx=xa:h1:xb;x=x';\ny=ya:h2:yb;y=y';\nu=zeros(m+1,n+1);\nu(1,:)=sin(pi*y);\nu(m+1,:)=(exp(2))*sin(pi*y);\nu(:,1)=0;u(:,n+1)=0;\nrow1=zeros(m-1,1);\nrow1(1,1)=2*(1/(h1^2)+1/(h2^2));row1(2,1)=-1/h1^2;\nC=toeplitz(row1);\nI=speye(m-1,m-1);\nD=(-1/h2^2)*I;\nA = kron(diag(ones(1,n-2),1) + diag(ones(1,n-2),-1),D)+ kron(diag(ones(1,n-1)),C);\nf=zeros(m-1,1);\nfor j = 1:n-1\n    f(1,j) = F2(x(2),y(j+1))+(1/h1^2)*u(1,j+1);\n    for k = 2:m-2\n        f(k,j) = F2(x(k+1),y(j+1));\n    end\n    f(m-1,j) = F2(x(m),y(j+1))+(1/h1^2)*u(m+1,j+1);\nend\nf(:,1) = f(:,1) - D*u(2:m,1);\nf(:,n-1) = f(:,n-1) - D*u(2:m,n+1);\nH = reshape(f,(m-1)*(n-1),1);\nU1=A\\H;\nU2=reshape(U1,m-1,n-1);\nu(2:m,2:n)=U2;\nF=zeros(m+1,n+1);\nfor k=1:m+1\n  for  j=1:n+1\n    F(k,j)=exp(x(k))*sin(pi*y(j));\n  end\nend\nerror = abs(F-u);\nMaxErr(i) = max(max(error));\nfigure(1)\nmesh(x,y,error(1:m+1,1:n+1));\nfigure(2)\nmesh(x,y,F(1:m+1,1:n+1));\nend\ndisp(MaxErr)\nfor i=1:3\nord=MaxErr(i)/MaxErr(i+1);\ndisp(ord);\nend"},{"name":"page53GS.m","page":53,"code":"xa = 0; xb = 2;\nya = 0; yb = 1;\nm = 64;\nn = 64;\nh1 = (xb - xa) / m;\nh2 = (yb - ya) / n;\nx = xa:h1:xb; x = x';\ny = ya:h2:yb; y = y';\nu = zeros(m+1, n+1);\nu(1, :) = sin(pi * y);\nu(m+1, :) = exp(2) * sin(pi * y);\nu(:, 1) = 0;\nu(:, n+1) = 0;\nF = zeros(m+1, n+1);\nfor k = 1:m+1\n    for j = 1:n+1\n        F(k, j) = exp(x(k)) * sin(pi * y(j));\n    end\nend\nrestart = true;\ntotal_iterations = 0;\n\nwhile restart\n    total_iterations = total_iterations + 1;  \n    restart = false;\n    \n    for kk = 1 \n        for i = 2:m\n            for j = 2:n\n                u(i, j) = (F2(x(i), y(j)) + (1/h2^2) * u(i, j-1) + (1/h1^2) * u(i-1, j)) / (2 * (1/h1^2 + 1/h2^2));\n            end\n        end\n        u=F;\n    end\n for kk = 2:1000 \n      for i = 2:m\n            for j = 2:n\n                u(i, j) = (F2(x(i), y(j)) + (1/h2^2) * u(i, j-1) + (1/h1^2) * u(i-1, j) + (1/h1^2) * F(i+1, j) + (1/h2^2) * F(i, j+1)) / (2 * (1/h1^2 + 1/h2^2));\n            end\n        end\n        \n     \n        if max(max(abs(u - F))) <= 5e-11\n            break;  \n        else\n           \n            if max(max(abs(u - F))) > 5e-11\n                 F = u; \n                restart = true; \n            end\n        end\n    end\nend\ndisp(['总循环次数: ', num2str(total_iterations)]); \ndisp(['最终的最大绝对差值: ', num2str(max(max(abs(u - F))))]); "},{"name":"page53JB.m","page":53,"code":"xa = 0; xb = 2;\nya = 0; yb = 1;\nm = 64;\nn = 64;\nh1 = (xb - xa) / m;\nh2 = (yb - ya) / n;\nx = xa:h1:xb; x = x';\ny = ya:h2:yb; y = y';\nu = zeros(m+1, n+1);\nu(1, :) = sin(pi * y);\nu(m+1, :) = exp(2) * sin(pi * y);\nu(:, 1) = 0;\nu(:, n+1) = 0;\nF = zeros(m+1, n+1);\nfor k = 1:m+1\n    for j = 1:n+1\n        F(k, j) = exp(x(k)) * sin(pi * y(j));\n    end\nend\nrestart = true;\ntotal_iterations = 0;\n\nwhile restart\n    total_iterations = total_iterations + 1;  \n    restart = false;\n    \n    for kk = 1:1000  \n        for i = 2:m\n            for j = 2:n\n                u(i, j) = (F2(x(i), y(j)) + (1/h2^2) * u(i, j-1) + (1/h1^2) * u(i-1, j) + (1/h1^2) * u(i+1, j) + (1/h2^2) * u(i, j+1)) / (2 * (1/h1^2 + 1/h2^2));\n            end\n        end\n        \n     \n        if max(max(abs(u - F))) <= 5e-11\n            break;  \n        else\n           \n            if max(max(abs(u - F))) > 5e-11\n                 F = u; \n                restart = true; \n            end\n        end\n    end\nend\ndisp(['总循环次数: ', num2str(total_iterations)]); \ndisp(['最终的最大绝对差值: ', num2str(max(max(abs(u - F))))]); "},{"name":"page68.m","page":68,"code":"for i=1:5\n    xa=0;xb=2;ya=0;yb=1;\n    m=4*2^i;\n    n=4*2^i;\nh1=(xb-xa)/m;\nh2=(yb-ya)/n;\nx=xa:h1:xb;x=x';\ny=ya:h2:yb;y=y';\nu=zeros(m+1,n+1);\nu(1,:)=sin(pi*y);\nu(m+1,:)=(exp(2))*sin(pi*y);\nu(:,1)=0;u(:,n+1)=0;\nrow1=zeros(m-1,1);\nrow1(1,1)=(5/3)*(1/(h1^2)+1/(h2^2));row1(2,1)=(-1/6)*(5/(h1^2)-1/h2^2);\nC=toeplitz(row1);\nrow2=zeros(m-1,1);\nrow2(1,1)=(-1/6)*(5/(h2^2)-1/(h1^2));row2(2,1)=(-1/12)*(1/(h1^2)+1/(h2^2));\nD=toeplitz(row2);\nA = kron(diag(ones(1,n-2),1) + diag(ones(1,n-2),-1),D)+ kron(diag(ones(1,n-1)),C);\nf=zeros(m-1,1);\nfor j = 1:n-1\n    f(1,j) = 1/144*F2(x(1),y(j))+10/144*F2(x(1),y(j+1))+1/144*F2(x(1),y(j+2))+...\n    10/144*F2(x(2),y(j))+100/144*F2(x(2),y(j+1))+10/144*F2(x(2),y(j+2))+...\n    1/144*F2(x(3),y(j))+10/144*F2(x(3),y(j+1))+1/144*F2(x(3),y(j+2))+...\n    (1/12)*(1/h1^2+1/h2^2)*u(1,j)+(1/6)*(5/h1^2-1/h2^2)*u(1,j+1)+(1/12)*(1/h1^2+1/h2^2)*u(1,j+2);\n    for k = 2:m-2\n    f(k,j) =  1/144*F2(x(k),y(j))+10/144*F2(x(k),y(j+1))+1/144*F2(x(k),y(j+2))+...\n    10/144*F2(x(k+1),y(j))+100/144*F2(x(k+1),y(j+1))+10/144*F2(x(k+1),y(j+2))+...\n    1/144*F2(x(k+2),y(j))+10/144*F2(x(k+2),y(j+1))+1/144*F2(x(k+2),y(j+2));\n    end\n    f(m-1,j) =  1/144*F2(x(m-1),y(j))+10/144*F2(x(m-1),y(j+1))+1/144*F2(x(m-1),y(j+2))+...\n    10/144*F2(x(m),y(j))+100/144*F2(x(m),y(j+1))+10/144*F2(x(m),y(j+2))+...\n    1/144*F2(x(m+1),y(j))+10/144*F2(x(m+1),y(j+1))+1/144*F2(x(m+1),y(j+2))+...\n    (1/12)*(1/h1^2+1/h2^2)*u(m+1,j)+(1/6)*(5/h1^2-1/h2^2)*u(m+1,j+1)+(1/12)*(1/h1^2+1/h2^2)*u(m+1,j+2);\nend\nf(:,1) = f(:,1) - D*u(2:m,1);\nf(:,n-1) = f(:,n-1) - D*u(2:m,n+1);\nH = reshape(f,(m-1)*(n-1),1);\nU1=A\\H;\nU2=reshape(U1,m-1,n-1);\nu(2:m,2:n)=U2;\nF=zeros(m+1,n+1);\nfor k=1:m+1\n  for  j=1:n+1\n    F(k,j)=exp(x(k))*sin(pi*y(j));\n  end\nend\nerror = abs(F-u);\nMaxErr(i) = max(max(error));\nfigure(1)\nhold on\nmesh(x,y,error(1:m+1,1:n+1));\nfigure(2)\nmesh(x,y,F(1:m+1,1:n+1));\nend\nformat short e\ndisp(MaxErr)\nfor i=1:4\nord=MaxErr(i)/MaxErr(i+1);\ndisp(ord);\nend"},{"name":"untitled.m","page":null,"code":"for ii=1:4\nx1 = 1; x2=2; y1=1;y2=2;t1 = 0; t2 = 1;\ns=0.1;\nm1=(4*2^ii);\nm2=m1;\nN=50;\nh1 = (x2-x1)/m1; \nh2=h1;\ndt = (t2-t1)/N;\nx = x1:h1:x2; x = x';\ny=y1:h2:y2; y = y';\nt = -s:dt:t2; t = t';\nn=s/dt;\nG=@(x,y,t)5*(t^4)*sin(pi*x)*sin(pi*y)+4*pi^2*(t^5+1)*sin(pi*x)*sin(pi*y)-((t^5+1)*sin(pi*x)*sin(pi*y))^2-(((t-0.1)^5+1)*sin(pi*x)*sin(pi*y))^2;\nu = zeros(m1+1,m2+1,N+n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        u(i,j,n+1) =sin(pi*x(i))*sin(pi*y(j));\n    end\nend\nfor i = 1:m1+1\n    for j = 1:m2+1\n        u(i,j,n+N+1) =2*sin(pi*x(i))*sin(pi*y(j));\n    end\nend\nfor i = 1:m1+1\n      for j = 1:m2+1\n    for k = 1:n+1\n        u(i,j,k) = (t(k)*5+1)*sin(pi*x(i))*sin(pi*y(j));\n    end\n      end\nend\na=2;\nr1 = a*dt /(h1^2) ;\nr2 = a*dt /(h2^2) ;\nI=speye(m1-1,m1-1);\nD=-r1*I;\nrow2 = zeros(m1-1, 1);\nrow2(1, 1) =-11/6+2*(r1+r2);row2(2, 1) = -r1;\nC = toeplitz(row2);\nA = kron(diag(ones(1,m2-2),1) + diag(ones(1,m2-2),-1),D)+ kron(diag(ones(1,m2-1)),C);\nfor k = n+1:N+n+1\n    H = zeros(m1-1,1);\nfor j = 2:m2\n    H(1, j-1) = -3*u(2, j, k-1) + 3/2*u(2, j, k-2) - 1/3*u(2, j, k-3) +r1*u(1, j, k)+dt * (G(x(2), y(j), t(k)) + (3*u(2, j, k-1) - 3*u(2, j, k-2) + u(2, j, k-3))^2 + (u(2, j, k-n))^2);\n    H(m1-1, j-1) = -3*u(m1, j, k-1) + 3/2*u(m1, j, k-2) - 1/3*u(m1, j, k-3) +r1*u(m1+1, j, k)+dt * (G(x(m1), y(j), t(k)) + (3*u(m1, j, k-1) - 3*u(m1, j, k-2) + u(m1, j, k-3))^2 + (u(m1, j, k-n))^2);\n    H(2:m1-2, j-1) = -3*u(3:m1-1, j, k-1) + 3/2*u(3:m1-1, j, k-2) - 1/3*u(3:m1-1, j, k-3)+dt * (G(x(3:m1-1), y(j), t(k)) + (3*u(3:m1-1, j, k-1) - 3*u(3:m1-1, j, k-2) + u(3:m1-1, j, k-3))^2 + (u(3:m1-1, j, k-n))^2); \n   H(:,1) = H(:,1) - D*u(2:m1,1,k);\nH(:,m2-1) = H(:,m2-1) - D*u(2:m1,m2+1,k);\nend\n\n\nF = reshape(H + L, (m1-1)*(m2-1), 1);\n\nU1 = A \\ F;\n\n\nu(2:m1, 2:m2, k) = reshape(U1, m1-1,m2-1);\nend\nF = zeros(m1+1,m2+1, N+n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        for l=1:N+n+1\n        F(i, j) =(t(l)*5+1)*sin(pi*x(i))*sin(pi*y(j));\n        end\n    end\nend\n    MaxErr(ii) = max(max(max(error)));\n   \nend\ndisp(MaxErr);\nfor i=1:3\n    ord(i) = MaxErr(i)/MaxErr(i+1);\nend\ndisp(ord);\n"},{"name":"untitled3.m","page":null,"code":"xa = 0;\nxb = 2;\nya = 0;\nyb = 4;\ntotal_error = zeros(3, 1);\nmaxerror = zeros(3, 1);\n\nfor ii = 1:3\n    m1 = 2^(ii+3);\n    m2 = m1;\n    h1 = (xb - xa) / m1;\n    h2 = (yb - ya) / m2;\n    x = linspace(xa, xb, m1+1)';\n    y = linspace(ya, yb, m2+1)';\n    u = zeros(m1+1, m2+1);\n    \n    for i = 1:m1+1\n        u(i, 1) = 0;\n        u(i, m2+1) = 0;\n    end\n    for j = 1:m2+1\n        u(1, j) = 0;\n        u(m1+1, j) = 0;\n    end\n    \n    row1 = zeros(m1-1, 1);\n    row1(1) = 10;\n    row1(2) = 1;\n    A = toeplitz(row1);\n    row2 = zeros(m1-1, 1);\n    row2(1) = -2;\n    row2(2) = 1;\n    B = toeplitz(row2);\n    I = speye(m2-1); \n    A1 = inv(kron(A, I));\n    B1 = kron(B, I);\n    A2 =inv( kron(I, A));\n    B2 = kron(I, B);\n    \n    C = (12/h1^2) * A1 * B1 + (12/h2^2) * A2 * B2;\nf=zeros(m1-1,m2-1);\nfor j = 1:m2-1\n    for k = 1:m1-1\n        f(k,j) = 2*pi^2*sin(pi*x(k+1))*sin(pi*y(j+1));\n    end\n    \nend\nH = reshape(f,(m1-1)*(m2-1),1);\n U1 = -C \\ H;\n  \n\n    U2 = reshape(U1, m1-1, m2-1);\n    u(2:m1, 2:m2) = U2;\n    \nF=zeros(m1+1,m2+1);\n    for i=1:m1+1\n        for j=1:m2+1\n            F(i,j)= sin(pi*x(i))*sin(pi*y(j));\n        end\n    end\n    \n\n    maxerror(ii) = max(max(abs(u - F)));\n    \n    disp(['最大误差 (层 ', num2str(ii), '): ', num2str(maxerror(ii))]);\nend\n\n\nfor i = 1:2\n    ord1 = maxerror(i) / maxerror(i+1);\n    disp(['最大误差收敛阶 (层 ', num2str(i), '): ', num2str(ord1)]);\nend"}],"topics":[{"name":"二维椭圆方程差分","desc":"对矩形区域上的 Poisson/椭圆型方程作五点差分离散，研究网格加密时的误差与收敛阶。","files":["example1.m","F2.m","page53.m","page68.m","untitled.m","untitled3.m"]},{"name":"Jacobi 与 Gauss-Seidel 迭代","desc":"用 Jacobi、Gauss-Seidel 迭代求解同一离散方程组，比较收敛速度。","files":["page53GS.m","page53JB.m"]}]},{"id":"ch3","name":"第三章","files":[{"name":"cgne.m","page":null,"code":"function [x, iter, residual] = cgne(A, b, x0, tol, maxIter)\n    m = length(b);\n    n = size(A, 2);\n    ATA = A' * A;\n    ATb = A' * b;\n    \n    r = b - A * x0; % 初始残差\n    p = A' * r; % 初始搜索方向\n    rsold = r' * r;\n    x = x0;\n\n    for i = 1:maxIter\n        Ap = A * p;\n        alpha = rsold / (Ap' * Ap);\n        x = x + alpha * p;\n        r = r - alpha * Ap;\n        rsnew = r' * r;\n        if sqrt(rsnew) < tol\n            break;\n        end\n        p = A' * r + (rsnew / rsold) * p;\n        rsold = rsnew;\n    end\n    iter = i;\n    residual = sqrt(rsnew);\nend"},{"name":"cgnr.m","page":null,"code":"% 设置 ii = 1 的参数\nii = 1;\nm = 10*2^(ii-1);  % 对应于 ii=1 时 m=10\nn = 100*4^(ii-1); % 对应于 ii=1 时 n=100\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = (x2-x1)/m; dt =(t2-t1)/n;\n\nr = dt /(h^2);\nrowA = [5/6+r, 1/12-r/2, zeros(1,m-3)];\nA = toeplitz(rowA, [5/6+r, 1/12-r/2, zeros(1,m-3)]');\nrowB = [5/6-r, 1/12+r/2, zeros(1,m-3)];\nB = toeplitz(rowB, [5/6-r, 1/12+r/2, zeros(1,m-3)]');\n\ndisp('Matrix A for ii=1:');\ndisp(A);\ndisp('Matrix B for ii=1:');\ndisp(B);\n\n% 测试向量 b\nb = ones(m-1, 1);\n\n% 定义最大迭代次数和容差\nmaxIter = 1000;\ntol = 1e-6;\nx0 = zeros(m-1, 1); % 初始猜测\n\n% 基于法方程的共轭梯度法\ndisp('CGNR Iteration Results:');\n[x_cgnr, iter, residual] = cgnr(B, b, x0, tol, maxIter);\ndisp(['CGNR converged at iteration ', num2str(iter), ' with residual ', num2str(residual)]);\n\n% SOR 方法\nomega = 1.5;  % 松弛因子\ndisp('SOR Iteration Results:');\ntry\n    [x_sor, iter, residual] = sor(B, b, omega, x0, tol, maxIter);\n    disp(['SOR converged at iteration ', num2str(iter), ' with residual ', num2str(residual)]);\ncatch ME\n    disp(ME.message);\nend\n\n% 基于KKT方程的SOR类迭代法\nC = eye(m-1); % 示例中的等式约束矩阵\nd = zeros(m-1, 1); % 示例中的等式约束向量\nz0 = [x0; zeros(m-1, 1)]; % 初始猜测\nlambda = 1e-6; % 正则化参数\ndisp('KKT-SOR Iteration Results:');\ntry\n    [z_kkt, iter, residual] = kkt_sor(B, C, b, d, omega, z0, tol, maxIter, lambda);\n    disp(['KKT-SOR converged at iteration ', num2str(iter), ' with residual ', num2str(residual)]);\ncatch ME\n    disp(ME.message);\nend"},{"name":"cholesky_decomposition.m","page":null,"code":"function L = cholesky_decomposition(A)\n    n = size(A, 1);\n    L = zeros(n);\n\n    for i = 1:n\n        for j = 1:i\n            sum = 0;\n            if (j == i)\n                for k = 1:j-1\n                    sum = sum + L(j, k)^2;\n                end\n                L(j, j) = sqrt(A(j, j) - sum);\n            else\n                for k = 1:j-1\n                    sum = sum + L(i, k) * L(j, k);\n                end\n                L(i, j) = (A(i, j) - sum) / L(j, j);\n            end\n        end\n    end\nend"},{"name":"extended_gcd.m","page":null,"code":"function [gcd_val, x_coeff, y_coeff] = extended_gcd(a, b)\n    if b == 0\n        gcd_val = a;\n        x_coeff = 1;\n        y_coeff = 0;\n    else\n        [gcd_val, temp_x, temp_y] = extended_gcd(b, mod(a, b));\n        x_coeff = temp_y;\n        y_coeff = temp_x - floor(a / b) * temp_y;\n    end\nend"},{"name":"f3.m","page":null,"code":"function y=f3(x,t)\ny = exp(-t).*sin(pi/4+pi/2.*x).*(pi^2/4.*exp(-4*t).*(sin(pi/4+pi/2*x)).^4-1);"},{"name":"givens_rotation.m","page":null,"code":"function [Q, R] = givens_rotation(A)\n    [m, n] = size(A);\n    R = A;\n    Q = eye(m);\n\n    for j = 1:min(m-1, n)\n        for i = m-1:-1:j\n            if R(i+1, j) ~= 0\n                r = sqrt(R(i, j)^2 + R(i+1, j)^2);\n                c = R(i, j) / r;\n                s = -R(i+1, j) / r;\n\n                G = eye(m);\n                G([i, i+1], [i, i+1]) = [c, s; -s, c];\n                \n                R = G' * R;\n                Q = Q * G;\n            end\n        end\n    end\n\n    Q = Q';\n    R = triu(R);\nend\n\n"},{"name":"householderqr.m","page":null,"code":"%=====================================================\nfunction  [Q,R]=householderqr(A)\n%---------------------------- General  M-file  comment\n%  Version   :  V1.0    \n%  Coded by  :  song.yz\n%  Date      :  2012-10-29 21:14:07          *星期一*\n%-----------------------------------------------------\n%  Purpose     :  Householder变换\n%  Reference   :     \n%-----------------------------------------------------\n%  Parameters :\n%       *.  Q-----正交矩阵\n%       *.  R-----上三角矩阵\n%       *.\n%----------------------------------------------------\n\n[M,N]=size(A);\n%获得矩阵维数\nA1=A;\nH1=zeros(M,M);\nfor j=1:M\n H1(j,j)=1;\nend \n%k表示对所有的列\nfor k=1:N\n %设置H矩阵初值，这里设置为单位矩阵\n  H0=zeros(M,M);\n  %设置为单位矩阵\n  for i=1:M\n  H0(i,i)=1;\n  end \n  s=0;\n  for i=k:M\n   s=s+A1(i,k)*A1(i,k);\n  end \n\n%算的向量的2范数  \n  s=sqrt(s);\n  u=zeros(N,1);\n%---------------------------------\n% 这段甚为重要，关系到数值稳定性问题\n% 目的是使得u的2范数尽可能大\n% 原则是，如果首元素大于零，则u的第一个元素是正+正\n%         如果首元素小于零，则u的第一个元素是负-负\n  if (A1(k,k)>=0) \n  u(k)=A1(k,k)+s;\n  else \n  u(k)=A1(k,k)-s;\n  end \n%-------------------------------  \n  for i=k+1:M\n  u(i)=A1(i,k);\n  end   \n  du=0;\n  for i=k:M\n  %求的单位u 长度平方\n  du=du+u(i)*u(i);\n  end \n\n  %计算得到大的H矩阵\n  for i=k:M\n    for j=k:M\n        H0(i,j)=-2*u(i)*u(j)/du;            \n        if i==j \n        H0(i,j)=1+H0(i,j);\n        end\n\n    end \n  end \n%千万要注意矩阵相乘的次序\n%先更新矩阵\nA2=H0*A1;\nA1=A2;\n%H1初值为单位矩阵，后逐步更新\nH1=H1*H0;\n%更新变换后的矩阵\nend \n\nQ=H1;\n\nR=A1;\nend\n\n%=====================================================\nfunction  x=uptri(A,b)\n%---------------------------- General  M-file  comment\n%  Version   :  V1.0\n%  Coded by  :  song.yz\n%  Date      :  2012-10-29 23:36:29          *星期一*\n%-----------------------------------------------------\n%  Parameters :\n%       *.  A---系数矩阵\n%       *.  b---右向量\n%----------------------------------------------------\n  N=length(b);\n  x(N)=b(N)/A(N,N);\n\n  for i=N-1:-1:1\n    x(i)=b(i);\n        for j=i+1:N\n        x(i)=x(i)-A(i,j)*x(j);\n        end\n        x(i)=x(i)/A(i,i);\n  end\n  x=x';\nend\n"},{"name":"houseQR.m","page":null,"code":"%=====================================================\nfunction  [Q,R]=houseQR(A)\n%---------------------------- General  M-file  comment\n%  Version   :  V1.0    \n%  Coded by  :  song.yz\n%  Date      :  2012-10-29 21:14:07          *星期一*\n%-----------------------------------------------------\n%  Purpose     :  Householder变换\n%  Reference   :     \n%-----------------------------------------------------\n%  Parameters :\n%       *.  Q-----正交矩阵\n%       *.  R-----上三角矩阵\n%       *.\n%----------------------------------------------------\n\n[M,N]=size(A);\n%获得矩阵维数\nA1=A;\nH1=zeros(M,M);\nfor j=1:M\n    H1(j,j)=1;\nend \n%k表示对所有的列\nfor k=1:N\n    %设置H矩阵初值，这里设置为单位矩阵\n    H0=zeros(M,M);\n    %设置为单位矩阵\n    for i=1:M\n        H0(i,i)=1;\n    end \n    s=0;\n    for i=k:M\n        s=s+A1(i,k)*A1(i,k);\n    end \n\n    %算的向量的2范数  \n    s=sqrt(s);\n    u=zeros(M,1);\n    %---------------------------------\n    % 这段甚为重要，关系到数值稳定性问题\n    % 目的是使得u的2范数尽可能大\n    % 原则是，如果首元素大于零，则u的第一个元素是正+正\n    %         如果首元素小于零，则u的第一个元素是负-负\n    if (A1(k,k)>=0) \n        u(k)=A1(k,k)+s;\n    else \n        u(k)=A1(k,k)-s;\n    end \n    %-------------------------------  \n    for i=k+1:M\n        u(i)=A1(i,k);\n    end   \n    du=0;\n    for i=k:M\n        %求的单位u 长度平方\n        du=du+u(i)*u(i);\n    end \n\n    %计算得到大的H矩阵\n    for i=k:M\n        for j=k:M\n            H0(i,j)=-2*u(i)*u(j)/du;            \n            if i==j \n                H0(i,j)=1+H0(i,j);\n            end\n        end \n    end \n    %千万要注意矩阵相乘的次序\n    %先更新矩阵\n    A2=H0*A1;\n    A1=A2;\n    %H1初值为单位矩阵，后逐步更新\n    H1=H1*H0;\n    %更新变换后的矩阵\nend \n\nQ=H1;\nR=A1;\nend\n\n%=====================================================\n"},{"name":"hss.m","page":null,"code":"\n% HSS 迭代\nfunction x = hss(A, b, alpha, maxIter, tol)\n    n = length(b);\n    H = (A + A') / 2;\n    S = (A - A') / 2;\n    I = eye(n);\n    \n    x = zeros(size(b));  % 初始猜测\n    residual = norm(b - A*x);\n    iter = 0;\n\n    while residual > tol && iter < maxIter\n        z = (alpha*I + H) \\ ((alpha*I - S)*x + b);\n        x = (alpha*I + S) \\ ((alpha*I - H)*z + b);\n        residual = norm(b - A*x);\n        iter = iter + 1;\n    end\n    disp(['HSS Iterations: ', num2str(iter)]);\nend\n\n"},{"name":"kkt_sor.m","page":null,"code":"function [z, iter, residual] = kkt_sor(A, C, b, d, omega, z0, tol, maxIter, lambda)\n    m = length(b);\n    n = length(d);\n    \n    % 确保C是满秩的\n    if rank(C) ~= size(C, 2)\n        error('Constraint matrix C is not full rank.');\n    end\n    \n    % 添加正则化项\n    KKT = [A, C'; C, lambda * eye(n)];\n    rhs = [b; d];\n    z = z0;\n    r = rhs - KKT*z;\n    residual = norm(r);\n\n    D = diag(diag(KKT));\n    L = tril(KKT, -1);\n    U = triu(KKT, 1);\n    M = inv(D/omega + L);\n    N = D*(omega-1)/omega - U;\n\n    for i = 1:maxIter\n        z = M * (N * z + rhs);\n        r = rhs - KKT*z;\n        residual = norm(r);\n        if isnan(residual) || isinf(residual)\n            disp('Residual became NaN or Inf, stopping iterations.');\n            break;\n        end\n        if residual < tol\n            break;\n        end\n    end\n    iter = i;\nend"},{"name":"lu_decomposition.m","page":null,"code":"function [L, U] = lu_decomposition(A)\n    n = size(A, 1);\n    L = eye(n);  % 初始化单位下三角矩阵\n    U = zeros(n);  % 初始化上三角矩阵\n    \n    for k = 1:n\n        % 更新U的第k行\n        U(k, k:n) = A(k, k:n);\n        \n        % 更新L的第k列\n        if k < n\n            L(k+1:n, k) = A(k+1:n, k) / A(k, k);\n        end\n        \n        % 更新剩余元素\n        for i = k+1:n\n            for j = k+1:n\n                A(i, j) = A(i, j) - L(i, k) * U(k, j);\n            end\n        end\n    end\nend"},{"name":"page107.m","page":107,"code":"for ii=1:4\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nM=10*2^(ii-1);\nN=200*4^(ii-1);\nh = (x2-x1)/M; dt = (t2-t1)/N;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu=zeros(M+1,N+1);\nu(:,1)=exp(x);\nu(1,:)=exp(t);\nu(M+1,:)=exp(1+t);\nr=dt/(h^2);\nrow1=zeros(M-1,1);\nrow1(1,1)=1+2*r;row1(2,1)=-r;\nA=toeplitz(row1);\nH=zeros(M-1,1);\nfor k=1:N\nH(1,1)=r*u(1,k+1)+u(2,k);\nH(M-1,1)=r*u(M+1,k+1)+u(M,k);\nfor i=2:M-2\nH(i,1)=u(i+1,k);\nend\nu(2:M,k+1)=A\\H;\nend\nF=zeros(M+1,N+1);\nfor i=1:M+1\n    for j=1:N+1\n        F(i,j)=exp(x(i)+t(j));\n    end\nend\nerror=abs(u-F);\nError1=abs(u(:,N+1)-F(:,N+1));\nmaxerror(ii)=max(max(error));\ndisp(maxerror(ii));\nfigure(1)\nplot(x,Error1,'k-.')\nhold on\nfigure(2)\nplot(x,u(:,N+1),'g-')\nplot(x,u(:,N+1),'k-.')\nhold on\n\nend\nfor j=1:3\n    ord=maxerror(j)/maxerror(j+1);\n    disp(ord);\nend\n"},{"name":"page115.m","page":115,"code":"\nm=10;\nn=100;\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = (x2-x1)/m; dt =(t2-t1)/n;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu = zeros(m+1, n+1);\n\n    u(:,1)=exp(x);\n    u(:,2)=exp(x+dt);\n    u(1,:)=exp(t);\n    u(m+1,:)=exp(1+t);\n\nr = dt /(h^2) ;\nrow1 = zeros(m-1, 1);\nrow1(1, 1) = -4*r; row1(2, 1) =2*r;\nA = toeplitz(row1);\nfor k = 2:n\n    H = zeros(m-1, 1);\n    H(1, 1) = 2*r * u(1, k) +u(1, k-1);\n    H(m-1, 1) =2*r * u(m+1, k) +u(m+1, k-1);\n\n    u(2:m, k+1) = A*u(2:m, k)+u(2:m,k-1) + H;\nend\n\n% 计算误差\nF = zeros(m+1, n+1);\nfor i = 1:m+1\n    for j = 1:n+1\n        F(i, j) = exp(x(i)+ t(j));\n    end\nend\nerror = abs(u - F);\nMaxErr = max(max(error));\n     disp(MaxErr);\n"},{"name":"page122.m","page":122,"code":"for ii=1:4\nm=10*2^(ii-1);\nn=100*4^(ii-1);\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = (x2-x1)/m; dt =(t2-t1)/n;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu = zeros(m+1, n+1);\n\n    u(:,1)=exp(x);\n    u(1,:)=exp(t);\n    u(m+1,:)=exp(1+t);\n\nr = dt /(h^2) ;\nrow1 = zeros(m-1, 1);\nrow1(1, 1) = 1+r; row1(2, 1) = -r/2;\nA = toeplitz(row1);\nrow1 = zeros(m-1, 1);\nrow1(1, 1) = 1-r; row1(2, 1) = r/2;\nB = toeplitz(row1);\n\nfor k = 1:n\n    H = zeros(m-1, 1);\n    H(1, 1) = r/2* u(1, k) +r/2*u(1, k+1);\n    H(m-1, 1) =r/2 * u(m+1, k) +r/2*u(m+1, k+1);\n\n    u(2:m, k+1) = A\\(B*u(2:m, k) + H);\nend\n\n% 计算误差\nF = zeros(m+1, n+1);\nfor i = 1:m+1\n    for j = 1:n+1\n        F(i, j) = exp(x(i)+ t(j));\n    end\nend\nerror = abs(u - F);\nMaxErr(ii) = max(max(error));\nfigure(1)\nplot(x,u(:,n+1));\nfigure(2)\nplot(x,F(:,n+1));\nfigure(3)\nhold on\nplot(x,abs(u(:,n+1)-F(:,n+1)));\nend\nfor l=1:4\n     disp(MaxErr(l));\nend\nfor j=1:3  \nord=MaxErr(j)/MaxErr(j+1);\ndisp(['收敛阶 ',': ', num2str(ord)]);\nend"},{"name":"page122EXAMPLE.m","page":122,"code":"x1 = 0; x2 = 1; t1 = 0; t2 = 1;\nM=10;\nN=10;\nh = (x2-x1)/M; dt = (t2-t1)/N;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu=zeros(M+1,N+1);\nu(:,1)=exp(x);\nu(1,:)=exp(t);\nu(M+1,:)=exp(1+t);\nr=dt/(h^2);\nrow1=zeros(M-1,1);\nrow1(1,1)=1+r;row1(2,1)=-r/2;\nA=toeplitz(row1);\nrow2=zeros(M-1,1);\nrow2(1,1)=1-r;row2(2,1)=r/2;\nB=toeplitz(row2);\nH=zeros(M-1,1);\nfor k=1:N\nH(1,1)=(r/2)*(u(1,k)+u(1,k+1));\nH(M-1,1)=(r/2)*(u(M+1,k)+u(M+1,k+1));\nu(2:M,k+1)=A\\(B*u(2:M,k)+H);\nend\nF=zeros(M+1,N+1);\nfor i=1:M+1\n    for j=1:N+1\n        F(i,j)=exp(x(i)+t(j));\n    end\nend\nerror=abs(u-F);\nmaxerror=max(max(error));\ndisp(maxerror);\n\n\n\n\n"},{"name":"page135.m","page":135,"code":"for ii=1:4\nm=10*2^(ii-1);\nn=100*4^(ii-1);\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = (x2-x1)/m; dt =(t2-t1)/n;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu = zeros(m+1, n+1);\n\n    u(:,1)=exp(x);\n    u(1,:)=exp(t);\n    u(m+1,:)=exp(1+t);\n\nr = dt /(h^2) ;\nrow1 = zeros(m-1, 1);\nrow1(1, 1) = 5/6+r; row1(2, 1) =1/12 -r/2;\nA = toeplitz(row1);\nrow1 = zeros(m-1, 1);\nrow1(1, 1) = 5/6-r; row1(2, 1) = 1/12+r/2;\nB = toeplitz(row1);\n\nfor k = 1:n\n    H = zeros(m-1, 1);\n    H(1, 1) = (1/12+r/2) * u(1, k) -(1/12-r/2)*u(1, k+1);\n    H(m-1, 1) =(1/12+r/2) * u(m+1, k) -(1/12-r/2)*u(m+1, k+1);\n\n    u(2:m, k+1) = A\\(B*u(2:m, k) + H);\nend\n\n% 计算误差\nF = zeros(m+1, n+1);\nfor i = 1:m+1\n    for j = 1:n+1\n        F(i, j) = exp(x(i)+ t(j));\n    end\nend\nerror = abs(u - F);\nMaxErr(ii) = max(max(error));\nfigure(1)\nplot(x,u(:,n+1));\nfigure(2)\nplot(x,F(:,n+1));\nfigure(3)\nhold on\nplot(x,abs(u(:,n+1)-F(:,n+1)));\nend\nfor l=1:3\n     disp(MaxErr(l));\nend\nfor j=1:3 \nord=MaxErr(j)/MaxErr(j+1);\ndisp(['收敛阶 ',': ', num2str(ord)]);\nend"},{"name":"page135EXAMPLE.m","page":135,"code":"x1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = 1/10; dt = 1/100;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu = zeros(11, 101);\n\n    u(:,1)=exp(x);\n    u(1,:)=exp(t);\n    u(11,:)=exp(1+t);\n\nr = dt /(h^2) ;\nrow1 = zeros(9, 1);\nrow1(1, 1) = 5/6+r; row1(2, 1) =1/12 -r/2;\nA = toeplitz(row1);\nrow1 = zeros(9, 1);\nrow1(1, 1) = 5/6-r; row1(2, 1) = 1/12+r/2;\nB = toeplitz(row1);\n\nfor k = 1:100\n    H = zeros(9, 1);\n    H(1, 1) = (1/12+r/2) * u(1, k) -(1/12-1/2)*u(1, k+1);\n    H(9, 1) =(1/12+r/2) * u(11, k) -(1/12-1/2)*u(11, k+1);\n\n    u(2:10, k+1) = A\\(B*u(2:10, k) + H);\nend\n\n% 计算误差\nF = zeros(11, 101);\nfor i = 1:11\n    for j = 1:101\n        F(i, j) = exp(x(i)+ t(j));\n    end\nend\nerror = abs(u - F);\nMaxErr = max(max(Error));\ndisp(['最大误差: ', num2str(MaxErr)]);\n"},{"name":"page135fft.m","page":135,"code":"for ii = 1:4\n    m = 10 * 2^(ii-1);\n    n = 100 * 4^(ii-1);\n    x1 = 0; x2 = 1; t1 = 0; t2 = 1;\n    h = (x2 - x1) / m;\n    dt = (t2 - t1) / n;\n    x = x1 : h : x2;\n    t = t1 : dt : t2;\n    u = zeros(m+1, n+1);\n\n    % 初始条件和边界条件\n    u(:, 1) = exp(x);\n    u(1, :) = exp(t);\n    u(m+1, :) = exp(1 + t);\n\n    r = dt / (h^2);\n\n    % 手动创建频率向量\n    k = 2 * pi * [0:(m/2-1), -m/2:-1] / (m * h);\n\n    % 时间步进\n    for k_time = 1:n\n        % 当前时刻的解\n        u_fft = fft(u(2:end-1, k_time));\n\n        % 构建右边项\n        H = zeros(m-1, 1);\n        H(1, 1) = (1/12 + r/2) * u(1, k_time) - (1/12 - r/2) * u(1, k_time+1);\n        H(m-1, 1) = (1/12 + r/2) * u(m+1, k_time) - (1/12 - r/2) * u(m+1, k_time+1);\n\n        % 计算下一时刻的解\n        u_next_fft = u_fft ./ (1 + r * k.^2) .* (1 - r * k.^2 * u_fft + fft(H));\n\n        % 反变换回空间域\n        u(2:end-1, k_time+1) = real(ifft(u_next_fft));\n    end\n\n    % 计算误差\n    F = zeros(m+1, n+1);\n    for i = 1:m+1\n        for j = 1:n+1\n            F(i, j) = exp(x(i) + t(j));\n        end\n    end\n    error = abs(u - F);\n    MaxErr(ii) = max(max(error));\n\n    % 绘图\n    figure(1)\n    plot(x, u(:, n+1));\n    hold on;\n    figure(2)\n    plot(x, F(:, n+1));\n    hold on;\n    figure(3)\n    plot(x, abs(u(:, n+1) - F(:, n+1)));\n    hold on;\nend\n\n% 输出最大误差\nfor l = 1:3\n    disp(MaxErr(l));\nend\n\n% 计算收敛阶\nfor j = 1:3\n    ord = MaxErr(j) / MaxErr(j+1);\n    disp(['收敛阶: ', num2str(ord)]);\nend"},{"name":"page145.m","page":145,"code":"for ii=1:4\nm=10*2^(ii-1);\nn=200*4^(ii-1);\nxa=0;xb=1;\nta=0;tb=1;\nh=(xb-xa)/m;\ndt=(tb-ta)/n;\nx=xa:h:xb;x=x';\nt=ta:dt:tb;t=t';\nu=zeros(m+1,n+1);\nu(:,1)=sin(pi/4+(pi/2)*x);\nu(1,:)=sqrt(2)/2*exp(-t);\nu(m+1,:)=sqrt(2)/2*exp(-t);\nr=dt/h^2;\nrow1=zeros(m-1,1);\nrow1(1,1)=-2;row1(2,1)=1;\nA=toeplitz(row1);\n\nfor k=1:n\nB=diag(u(2:m,k).^4);\n        H=zeros(m-1,1);\n        H(1,1)=r*u(1,k).*u(2,k).^4;\n        H(m-1,1)=r*u(m+1,k).*u(m,k)^4;\n        F=zeros(m-1,1);\n        F(1:m-1,1)=f3(x(2:m),t(k));\n        u(2:m,k+1)=u(2:m,k)+r*B*A*u(2:m,k)+H+dt*F ;\nend\nf=zeros(m+1,n+1);\nfor e=1:m+1\n   for g=1:n+1\n       f(e,g)=exp(-t(g))*sin(pi/4+(pi/2)*x(e));\n   end\nend\nerror=abs(u-f);\nfigure(1)\nhold on\nplot(x,error(1:m+1,n+1));\nMaxErr(ii) = max(max(error));\ndisp(MaxErr(ii));\nend\nfor j=1:3\n    ord=MaxErr(j)/MaxErr(j+1);\n    disp(ord);\nend\n\nfigure(2)\nplot(x,f(1:m+1,n+1));\nfigure(3)\nplot(x,u(1:m+1,n+1));\n[X, T] = meshgrid(x, t);\nmesh(X, T, error');\n"},{"name":"page150.m","page":150,"code":"for ii=1:4\nm=10*2^(ii-1);\nn=m^2;\nxa=0;xb=1;\nta=0;tb=1;\nh=(xb-xa)/m;\ndt=(tb-ta)/n;\nx=xa:h:xb;x=x';\nt=ta:dt:tb;t=t';\nu=zeros(m+1,n+1);\nu(:,1)=sin(pi/4+(pi/2)*x);\nu(1,:)=sqrt(2)/2*exp(-t);\nu(m+1,:)=sqrt(2)/2*exp(-t);\nr=dt/h^2;\nrow1=zeros(m-1,1);\nrow1(1,1)=-2;row1(2,1)=1;\nA=toeplitz(row1);\nI=speye(m-1,m-1);\nfor k = 1:n\n B = diag(u(2:m,k).^4);\n    H = zeros(m-1,1);\n    H(1,1) = r*u(1,k+1)*u(2,k).^4;\n    H(m-1,1) = r*u(m+1,k+1)*u(m,k).^4;\n    u(2:m,k+1) = (I-r*B*A)\\(u(2:m,k) + dt*f3(x(2:m),t(k+1)) + H);\nend\nf=zeros(m+1,n+1);\nfor e=1:m+1\n   for g=1:n+1\n       f(e,g)=exp(-t(g))*sin(pi/4+(pi/2)*x(e));\n   end\nend\nerror=abs(u-f);\nfigure(4)\n[X, T] = meshgrid(x, t);\nmesh(X, T, error');\nhold on\nfigure(1)\nplot(x,error(1:m+1,n+1));\nhold on\nMaxErr(ii) = max(max(error));\ndisp(MaxErr(ii));\nend\nfor j=1:3\n    ord=MaxErr(j)/MaxErr(j+1);\n    disp(ord);\nend\nfigure(2)\nplot(x,f(1:m+1,n+1));\nfigure(3)\nplot(x,u(1:m+1,n+1));\n\n"},{"name":"page161.m","page":161,"code":"function MaxErr = page161(M, N, p)\n\n    format short e\n    xa = 0; xb = 1; h = (xb - xa) / M;\n    Ta = 0; Tb = 1; dt = (Tb - Ta) / N;\n    x = xa:h:xb; x = x';\n    t = Ta:dt:Tb; t = t';\n\n    % 系数矩阵和边界条件\n    a = 1; r = a * dt / h^2;\n    u = zeros(M + 1, N + 1);\n    u(:,1) = u1(x); % 初始条件\n    u(1,:) = sqrt(2)/2 * exp(-t);\n    u(M + 1,:) = sqrt(2)/2 * exp(-t);\n    row = zeros(M - 1, 1); row(1, 1) = -2; row(2) = 1;\n    A = toeplitz(row); I = eye(M - 1);\n\n    % 计算第一层次\n    U = 1 / 2 * (u1(x) + dt / 2 * ((u1(x)).^4 .* u2(x) + f3(x, 0))).^4;\n    B = diag(U(2:M));\n    H1 = zeros(M - 1, 1);\n    H1(1) = r * U(2) * u(1, 2); \n    H1(M - 1) = r * U(M) * u(M + 1, 2);\n    H2 = zeros(M - 1, 1);\n    H2(1) = r * U(2) * u(1, 1); \n    H2(M - 1) = r * U(M) * u(M + 1, 1);\n    t_half = (t(1) + t(2)) / 2;\n    u(2:M,2) = (I - r * B * A) \\ ((I + r * B * A) * u(2:M,1) + dt * f3(x(2:M), t_half) + H1 + H2);\n\n    % 计算第 2 到 N 层次\n    for k = 2:N\n        C = diag(u(2:M, k).^4);\n        H = zeros(M - 1, 1);\n        H(1) = r * u(1, k + 1) * u(2, k).^4 + r * u(1, k - 1) * u(2, k).^4;\n        H(M - 1) = r * u(M + 1, k + 1) * u(M, k).^4 + r * u(M + 1, k - 1) * u(M, k).^4;\n        u(2:M, k + 1) = (I - r * C * A) \\ (u(2:M, k - 1) + r * C * A * u(2:M, k - 1) + 2 * dt * f3(x(2:M), t(k)) + H);\n    end\n\n    % 计算误差和精确解\n    T = zeros(M + 1, N + 1);\n    for i = 1:M + 1\n        for j = 1:N + 1\n            T(i, j) = exp(-t(j)) * sin(pi / 4 + pi / 2 * x(i));\n        end\n    end\n    Error = abs(u - T);\n    MaxErr = max(max(Error));\n\n    % 绘制图形\n    if p == 1\n        figure(1)\n        mesh(u)\n        xlabel('t'), ylabel('x'), zlabel('u(x,t)')\n        \n        figure(2)\n        mesh(t(2:end - 1), x(2:end - 1), Error(2:end - 1, 2:end - 1))\n        xlabel('t'), ylabel('x'), zlabel('Error')\n        hold on\n    end\nend\n\n\n\n"},{"name":"page161run.m","page":161,"code":"\nclear all; clc;\nM = 10; N = 10;\np = 0;\nii = 6;\nformat short e\nErr = zeros(1, ii);\nfor i = 1:ii\n    MaxErr = page161(M * 2^(i - 1), N * 4^(i - 1), p);\n    Err(i) = MaxErr;\nend\nErr\nOrd = log2(Err(1:end - 1) ./ Err(2:end))"},{"name":"page93.m","page":93,"code":"for ii=1:4\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nM=10*2^(ii-1);\nN=200*4^(ii-1);\nh = (x2-x1)/M; dt = (t2-t1)/N;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu=zeros(M+1,N+1);\nu(:,1)=exp(x);\nu(1,:)=exp(t);\nu(M+1,:)=exp(1+t);\nr=dt/(h^2);\nrow1=zeros(M-1,1);\nrow1(1,1)=1-2*r;row1(2,1)=r;\nA=toeplitz(row1);\nH=zeros(M-1,1);\nfor k=1:N\nH(1,1)=r*u(1,k);\nH(M-1,1)=r*u(M+1,k);\nu(2:M,k+1)=A*u(2:M,k)+H;\nend\nF=zeros(M+1,N+1);\nfor i=1:M+1\n    for j=1:N+1\n        F(i,j)=exp(x(i)+t(j));\n    end\nend\nerror=abs(u-F);\nError1=abs(u(:,N+1)-F(:,N+1));\nmaxerror(ii)=max(max(error));\ndisp(maxerror(ii));\nfigure(1)\nplot(x,Error1,'k-.')\nhold on\nend\nfor j=1:3\n    ord=maxerror(j)/maxerror(j+1);\n    disp(ord);\nend\n\n\n"},{"name":"phss.m","page":null,"code":"% PHSS 迭代\nfunction x = phss(A, b, alpha, maxIter, tol)\n    n = length(b);\n    H = (A + A') / 2;\n    S = (A - A') / 2;\n    I = eye(n);\n    \n    x = zeros(size(b));  % 初始猜测\n    residual = norm(b - A*x);\n    iter = 0;\n\n    while residual > tol && iter < maxIter\n        z = (alpha*I + H) \\ ((alpha*I - S)*x + b);\n        x = (alpha*I + H) \\ ((alpha*I - S)*z + b);\n        residual = norm(b - A*x);\n        iter = iter + 1;\n    end\n    disp(['PHSS Iterations: ', num2str(iter)]);\nend"},{"name":"sor.m","page":null,"code":"function [x, iter, residual] = sor(A, b, omega, x0, tol, maxIter)\n    n = length(b);\n    D = diag(diag(A));\n    L = tril(A, -1);\n    U = triu(A, 1);\n    \n    % 使用 Jacobi 预处理\n    M = inv(D);  % Jacobi 预处理\n    A_precond = M * A;\n    b_precond = M * b;\n\n    M = inv(D/omega + L);\n    N = D*(omega-1)/omega - U;\n    x = x0;\n    r = b_precond - A_precond*x;\n    residual = norm(r);\n\n    for i = 1:maxIter\n        x = M * (N * x + b_precond);\n        r = b_precond - A_precond*x;\n        residual = norm(r);\n        if isnan(residual) || isinf(residual)\n            disp('Residual became NaN or Inf, stopping iterations.');\n            break;\n        end\n        if residual < tol\n            break;\n        end\n    end\n    iter = i;\nend"},{"name":"ssor.m","page":null,"code":"% SSOR 迭代\nfunction x = ssor(A, b, omega, maxIter, tol)\n    D = diag(diag(A));\n    L = tril(A, -1);\n    U = triu(A, 1);\n    M = inv(D/omega + L) * (D*(2/omega - 1) - U);\n    x = zeros(size(b));  % 初始猜测\n    residual = norm(b - A*x);\n    iter = 0;\n\n    while residual > tol && iter < maxIter\n        x = M * x + inv(D/omega + L) * b;\n        residual = norm(b - A*x);\n        iter = iter + 1;\n    end\n    disp(['SSOR Iterations: ', num2str(iter)]);\nend"},{"name":"u1.m","page":null,"code":"function y = u1(x)\ny = sin(pi/4+pi/2*x);"},{"name":"u2.m","page":null,"code":"function y = u2(x)\ny = -(pi/2)^2*sin(pi/4+pi/2*x);\n"},{"name":"untitled19.m","page":null,"code":"% 初始化最大误差数组\nMaxErr = zeros(4, 1);\n\nfor ii=1:4\n    m = 10*2^(ii-1);\n    n = 100*4^(ii-1);\n    x1 = 0; x2 = 1; t1 = 0; t2 = 1;\n    h = (x2-x1)/m; dt =(t2-t1)/n;\n    x = linspace(x1, x2, m+1)'; % 使用linspace来生成等间距点\n    t = linspace(t1, t2, n+1)';\n    u = zeros(m+1, n+1);\n\n    % 初始条件和边界条件\n    u(:,1) = exp(x);\n    u(1,:) = exp(t);\n    u(m+1,:) = exp(1+t);\n\n    r = dt /(h^2);\n    \n    % 构建矩阵A和B\n    rowA = [5/6+r, 1/12-r/2];\n    A = toeplitz([rowA(1), rowA(2), zeros(1,m-3)], [rowA(1), rowA(2), zeros(1,m-3)]);\n    rowB = [5/6-r, 1/12+r/2];\n    B = toeplitz([rowB(1), rowB(2), zeros(1,m-3)], [rowB(1), rowB(2), zeros(1,m-3)]);\n\n    for k = 1:n\n        H = zeros(m-1, 1);\n        H(1) = (1/12+r/2) * u(1, k) -(1/12-r/2)*u(1, k+1);\n        H(end) =(1/12+r/2) * u(m+1, k) -(1/12-r/2)*u(m+1, k+1);\n\n        % 对每一层都进行QR分解，以确保数值稳定性\n        [Q, R] = qr(B);  % Householder QR 分解\n        \n        % 确保 A*u(2:m, k) 和 H 的维度一致\n        rhs = A * u(2:m, k) + H;  % 右端项\n        \n        % 确保 Q' 和 rhs 的维度一致\n        b = Q' * rhs;  % 求解右端项\n        u(2:m, k+1) = R\\b;  % 回代求解上三角系统 Rx = b\n    end\n\n    % 计算误差\n    [X, T] = meshgrid(x, t); % 创建网格数据\n    F = exp(X + T); % 理论解\n    error = abs(u - F');\n    MaxErr(ii) = max(error(:));\nend\n\n% 输出最大误差和收敛阶数\nfor l=1:3\n    disp(['Max Error for ii=', num2str(l), ': ', num2str(MaxErr(l))]);\nend\nfor j=1:3 \n    ord = log2(MaxErr(j)/MaxErr(j+1));\n    if isfinite(ord) && ord > 0\n        disp(['收敛阶 ',': ', num2str(ord)]);\n    else\n        disp('收敛阶未定义或为负，请检查代码');\n    end\nend"},{"name":"untitled23.m","page":null,"code":"\n\n% 设置 ii = 4 的参数\nii = 1;\nm = 10*2^(ii-1);\nn = 100*4^(ii-1);\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = (x2-x1)/m; dt =(t2-t1)/n;\n\nr = dt /(h^2);\nrowA = [5/6+r, 1/12-r/2, zeros(1,m-3)];\nA = toeplitz(rowA, [5/6+r, 1/12-r/2, zeros(1,m-3)]');\nrowB = [5/6-r, 1/12+r/2, zeros(1,m-3)];\nB = toeplitz(rowB, [5/6-r, 1/12+r/2, zeros(1,m-3)]');\n\ndisp('Matrix A:');\ndisp(A);\ndisp('Matrix B:');\ndisp(B);\n\n% Householder QR 分解\n[Q_h, R_h] = qr(B);  % Householder QR 分解\ndisp('Householder QR Decomposition:');\ndisp('Q:');\ndisp(Q_h);\ndisp('R:');\ndisp(R_h);\n\n% Givens 旋转\n[Q_g, R_g] = givens_rotation(B);  % Givens 旋转\ndisp('Givens Rotation:');\ndisp('Q:');\ndisp(Q_g);\ndisp('R:');\ndisp(R_g);"},{"name":"untitled27.m","page":null,"code":"function [Q, R] = givens_rotation(A)\n    [m, n] = size(A);\n    R = A;\n    Q = eye(m);\n\n    for j = 1:min(m-1, n)\n        for i = m-1:-1:j\n            if R(i+1, j) ~= 0\n                r = sqrt(R(i, j)^2 + R(i+1, j)^2);\n                c = R(i, j) / r;\n                s = -R(i+1, j) / r;\n\n                G = eye(m);\n                G([i, i+1], [i, i+1]) = [c, s; -s, c];\n                \n                R = G' * R;\n                Q = Q * G;\n            end\n        end\n    end\n\n    Q = Q';\n    R = triu(R);\nend\n\n% 设置 ii = 1 的参数\nii = 1;\nm = 10*2^(ii-1);  % 对应于 ii=1 时 m=10\nn = 100*4^(ii-1); % 对应于 ii=1 时 n=100\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = (x2-x1)/m; dt =(t2-t1)/n;\n\nr = dt /(h^2);\nrowA = [5/6+r, 1/12-r/2, zeros(1,m-3)];\nA = toeplitz(rowA, [5/6+r, 1/12-r/2, zeros(1,m-3)]');\nrowB = [5/6-r, 1/12+r/2, zeros(1,m-3)];\nB = toeplitz(rowB, [5/6-r, 1/12+r/2, zeros(1,m-3)]');\n\ndisp('Matrix A for ii=1:');\ndisp(A);\ndisp('Matrix B for ii=1:');\ndisp(B);\n\n% SSOR 迭代\nfunction x = ssor(A, b, omega, maxIter, tol)\n    D = diag(diag(A));\n    L = tril(A, -1);\n    U = triu(A, 1);\n    M = inv(D/omega + L) * (D*(2/omega - 1) - U);\n    x = zeros(size(b));  % 初始猜测\n    residual = norm(b - A*x);\n    iter = 0;\n\n    while residual > tol && iter < maxIter\n        x = M * x + inv(D/omega + L) * b;\n        residual = norm(b - A*x);\n        iter = iter + 1;\n    end\n    disp(['SSOR Iterations: ', num2str(iter)]);\nend\n\n% HSS 迭代\nfunction x = hss(A, b, alpha, maxIter, tol)\n    n = length(b);\n    H = (A + A') / 2;\n    S = (A - A') / 2;\n    I = eye(n);\n    \n    x = zeros(size(b));  % 初始猜测\n    residual = norm(b - A*x);\n    iter = 0;\n\n    while residual > tol && iter < maxIter\n        z = (alpha*I + H) \\ ((alpha*I - S)*x + b);\n        x = (alpha*I + S) \\ ((alpha*I - H)*z + b);\n        residual = norm(b - A*x);\n        iter = iter + 1;\n    end\n    disp(['HSS Iterations: ', num2str(iter)]);\nend\n\n% PHSS 迭代\nfunction x = phss(A, b, alpha, maxIter, tol)\n    n = length(b);\n    H = (A + A') / 2;\n    S = (A - A') / 2;\n    I = eye(n);\n    \n    x = zeros(size(b));  % 初始猜测\n    residual = norm(b - A*x);\n    iter = 0;\n\n    while residual > tol && iter < maxIter\n        z = (alpha*I + H) \\ ((alpha*I - S)*x + b);\n        x = (alpha*I + H) \\ ((alpha*I - S)*z + b);\n        residual = norm(b - A*x);\n        iter = iter + 1;\n    end\n    disp(['PHSS Iterations: ', num2str(iter)]);\nend\n\n% 测试向量 b\nb = ones(m-1, 1);\n\n% SSOR 参数\nomega = 1.5;  % 松弛因子\nmaxIter = 1000;\ntol = 1e-6;\n\n% HSS 和 PHSS 参数\nalpha = 1.0;\n\ndisp('SSOR Iteration Results:');\nx_ssor = ssor(B, b, omega, maxIter, tol);\n\ndisp('HSS Iteration Results:');\nx_hss = hss(B, b, alpha, maxIter, tol);\n\ndisp('PHSS Iteration Results:');\nx_phss = phss(B, b, alpha, maxIter, tol);"},{"name":"untitled31.m","page":null,"code":"% 设置 ii = 1 的参数\nii = 1;\nm = 10*2^(ii-1);  % 对应于 ii=1 时 m=10\nn = 100*4^(ii-1); % 对应于 ii=1 时 n=100\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = (x2-x1)/m; dt =(t2-t1)/n;\n\nr = dt /(h^2);\nrowA = [5/6+r, 1/12-r/2, zeros(1,m-3)];\nA = toeplitz(rowA, [5/6+r, 1/12-r/2, zeros(1,m-3)]');\nrowB = [5/6-r, 1/12+r/2, zeros(1,m-3)];\nB = toeplitz(rowB, [5/6-r, 1/12+r/2, zeros(1,m-3)]');\n\ndisp('Matrix A for ii=1:');\ndisp(A);\ndisp('Matrix B for ii=1:');\ndisp(B);\n\n% 测试向量 b\nb = ones(m-1, 1);\n\n% 定义最大迭代次数和容差\nmaxIter = 1000;\ntol = 1e-6;\n\n% 共轭梯度（CG）方法\nif all(eig(B) > 0) % 确保矩阵是正定的\n    disp('CG Iteration Results:');\n    [x_cg, flag, relres, iter] = pcg(B, b, tol, maxIter);\n    if flag == 0\n        disp(['CG converged at iteration ', num2str(iter), ' with relative residual ', num2str(relres)]);\n    else\n        disp('CG did not converge.');\n    end\nelse\n    disp('Matrix B is not positive definite. CG cannot be used.');\nend\n\n% MINRES 方法\ndisp('MINRES Iteration Results:');\n[x_minres, flag, relres, iter] = minres(B, b, tol, maxIter);\nif flag == 0\n    disp(['MINRES converged at iteration ', num2str(iter), ' with relative residual ', num2str(relres)]);\nelse\n    disp('MINRES did not converge.');\nend\n\n% LSQR 方法\ndisp('LSQR Iteration Results:');\n[x_lsqr, flag, relres, iter] = lsqr(B, b, tol, maxIter);\nif flag == 0\n    disp(['LSQR converged at iteration ', num2str(iter), ' with relative residual ', num2str(relres)]);\nelse\n    disp('LSQR did not converge.');\nend"},{"name":"untitled37.m","page":null,"code":"% 设置 ii = 1 的参数\nii = 1;\nm = 10*2^(ii-1);  % 对应于 ii=1 时 m=10\nn = 100*4^(ii-1); % 对应于 ii=1 时 n=100\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = (x2-x1)/m; dt =(t2-t1)/n;\n\nr = dt /(h^2);\nrowA = [5/6+r, 1/12-r/2, zeros(1,m-3)];\nA = toeplitz(rowA, [5/6+r, 1/12-r/2, zeros(1,m-3)]');\nrowB = [5/6-r, 1/12+r/2, zeros(1,m-3)];\nB = toeplitz(rowB, [5/6-r, 1/12+r/2, zeros(1,m-3)]');\n\ndisp('Matrix A for ii=1:');\ndisp(A);\ndisp('Matrix B for ii=1:');\ndisp(B);\n\n% 测试向量 b\nb = ones(m-1, 1);\n\n% 定义最大迭代次数和容差\nmaxIter = 1000;\ntol = 1e-6;\nx0 = zeros(m-1, 1); % 初始猜测\n\n% 基于法方程的共轭梯度法\ndisp('CGNR Iteration Results:');\n[x_cgnr, iter, residual] = cgnr(B, b, x0, tol, maxIter);\ndisp(['CGNR converged at iteration ', num2str(iter), ' with residual ', num2str(residual)]);\n\n\n\n"},{"name":"untitled40.m","page":null,"code":"% 设置 ii = 1 的参数\nii = 1;\nm = 10*2^(ii-1);  % 对应于 ii=1 时 m=10\nn = 100*4^(ii-1); % 对应于 ii=1 时 n=100\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nh = (x2-x1)/m; dt =(t2-t1)/n;\n\nr = dt /(h^2);\nrowA = [5/6+r, 1/12-r/2, zeros(1,m-3)];\nA = toeplitz(rowA, [5/6+r, 1/12-r/2, zeros(1,m-3)]');\nrowB = [5/6-r, 1/12+r/2, zeros(1,m-3)];\nB = toeplitz(rowB, [5/6-r, 1/12+r/2, zeros(1,m-3)]');\n\ndisp('Matrix A for ii=1:');\ndisp(A);\ndisp('Matrix B for ii=1:');\ndisp(B);\n\n% 测试向量 b\nb = ones(m-1, 1);\n\n% LU 分解\ndisp('Performing LU Decomposition on Matrix A:');\n[L_A, U_A] = lu_decomposition(A);\ndisp('Lower Triangular Matrix L for A:');\ndisp(L_A);\ndisp('Upper Triangular Matrix U for A:');\ndisp(U_A);\n\ndisp('Performing LU Decomposition on Matrix B:');\n[L_B, U_B] = lu_decomposition(B);\ndisp('Lower Triangular Matrix L for B:');\ndisp(L_B);\ndisp('Upper Triangular Matrix U for B:');\ndisp(U_B);"},{"name":"uptri.m","page":null,"code":"function  x=uptri(A,b)\n%---------------------------- General  M-file  comment\n%  Version   :  V1.0\n%  Coded by  :  song.yz\n%  Date      :  2012-10-29 23:36:29          *星期一*\n%-----------------------------------------------------\n%  Parameters :\n%       *.  A---系数矩阵\n%       *.  b---右向量\n%----------------------------------------------------\n    N=length(b);\n    x(N)=b(N)/A(N,N);\n\n    for i=N-1:-1:1\n        x(i)=b(i);\n        for j=i+1:N\n            x(i)=x(i)-A(i,j)*x(j);\n        end\n        x(i)=x(i)/A(i,i);\n    end\n    x=x';\nend\n\n"}],"topics":[{"name":"矩阵分解与直接法","desc":"LU、Cholesky、Givens、Householder QR 等矩阵分解与上三角回代。","files":["cholesky_decomposition.m","givens_rotation.m","householderqr.m","houseQR.m","lu_decomposition.m","untitled27.m","uptri.m"]},{"name":"迭代法与 Krylov 方法","desc":"SOR、SSOR、HSS、PHSS、KKT-SOR、CGNE、CGNR 等迭代求解器。","files":["cgne.m","cgnr.m","hss.m","kkt_sor.m","phss.m","sor.m","ssor.m"]},{"name":"一维抛物方程差分","desc":"热传导方程显式、隐式、Crank–Nicolson、FFT 等格式与收敛阶实验。","files":["page107.m","page115.m","page122.m","page122EXAMPLE.m","page135.m","page135EXAMPLE.m","page135fft.m","page145.m","page150.m","page161.m","page161run.m","page93.m","untitled19.m","untitled23.m","untitled31.m","untitled37.m","untitled40.m"]},{"name":"辅助函数","desc":"真解、右端项、扩展欧几里得等辅助脚本。","files":["extended_gcd.m","f3.m","u1.m","u2.m"]}]},{"id":"ch4","name":"第四章","files":[{"name":"page180.m","page":180,"code":"for ii=1:4\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nM=10*2^(ii-1);\nN=2*M;\nh = (x2-x1)/M; dt = (t2-t1)/N;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu = zeros(M+1,N+1);\nu(1,:)=exp(t);\nu(M+1,:)=exp(1+t);\nu(:,1)=exp(x);\nfor i=2:M\nu(i,2)=u(i,1)+dt*exp(x(i))+((dt)^2/2)*(((u(i-1,1)-2*u(i,1)+u(i+1,1))/h^2));\nend\ns =dt /h;\nrow1 = zeros(M-1, 1);\nrow1(2, 1) = s^2;row1(1, 1) = 2*(1-s^2); \nA=toeplitz(row1);\nfor k = 2:N\n     H = zeros(M-1, 1);\n    H(1, 1) =s^2*u(1,k);\n    H(M-1, 1) =s^2*u(M+1,k);\n\nu(2:M,k+1)=A*u(2:M,k)-u(2:M,k-1)+H;\nend\n% 计算误差\nF = zeros(M+1, N+1);\nfor i = 1:M+1\n    for j = 1:N+1\n        F(i, j) =exp(x(i)+t(j));\n    end\nend\nerror = abs(u-F);\nMaxErr(ii) = max(max(error));\ndisp( MaxErr(ii));\nfigure(1)\nhold on\nplot(x,abs(u(:,1+N)-F(:,1+N)));\nend\nfor j=1:3\nOrd = (MaxErr(j)/MaxErr(j+1));\ndisp(['收敛阶为：',num2str(Ord)])\nend\n\nfigure(2)\nplot(x,u(:,1+N));\nfigure(3)\nplot(x,F(:,1+N));\n    [X, T] = meshgrid(x, t);\nerror = error';\n    figure(4)\n    mesh(X, T, error);\n "},{"name":"page197.m","page":197,"code":"for ii=1:4\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nM=10*2^(ii-1);\nN=10*2^(ii-1);\nh = (x2-x1)/M; dt = (t2-t1)/N;\ns =dt /h;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu = zeros(M+1,N+1);\nu(1,:)=exp(t);\nu(M+1,:)=exp(1+t);\nu(:,1)=exp(x);\nrow1 = zeros(M-1, 1);\nrow1(2, 1) = -s^2/2;row1(1, 1) = 2+s^2; \nA=toeplitz(row1);\nrow2 = zeros(M-1, 1);\nrow2(2, 1) = s^2/2;row2(1, 1) = 2-s^2; \nB=toeplitz(row2);\nrow3 = zeros(M-1, 1);\nrow3(2, 1) = -s^2/2;row3(1, 1) = 1+s^2; \nC=toeplitz(row3);\nrow4 = zeros(M-1, 1);\nrow4(2, 1) = s^2/2;row4(1, 1) = -1-s^2; \nD=toeplitz(row4);\nfor k = 2:N\n     H1 = zeros(M-1, 1);\n    H1(1, 1) =(s^2/2)*(u(1,1)+u(1,2));\n    \n    H1(M-1, 1) =(s^2/2)*(u(M+1,1)+u(M+1,2));\n\nu(2:M,2)=A\\(B*u(2:M,1)+H1+2*dt*exp(x(2:M)));\nend\nfor k = 2:N\n     H = zeros(M-1, 1);\n    H(1, 1) =s^2/2*(u(1,k+1)+u(1,k-1));\n    \n    H(M-1, 1) =s^2/2*(u(M+1,k+1)+u(M+1,k-1));\n\nu(2:M,k+1)=C\\(D*u(2:M,k-1)+H+2*u(2:M,k));\nend\n% 计算误差\nF = zeros(M+1, N+1);\nfor i = 1:M+1\n    for j = 1:N+1\n        F(i, j) =exp(x(i)+t(j));\n    end\nend\nerror = abs(u-F);\nMaxErr(ii) = max(max(error));\ndisp( MaxErr(ii));\nfigure(1)\nhold on\nplot(x,abs(u(:,1+N)-F(:,1+N)))\nend\nfor j=1:3\nOrd = (MaxErr(j)/MaxErr(j+1));\ndisp(['收敛阶为：',num2str(Ord)])\nend\nfigure(2)\nplot(x,u(:,1+N));\nfigure(3)\nplot(x,F(:,1+N));\n    [X, T] = meshgrid(x, t);\nerror = error';\n    figure(4)\n    mesh(X, T, error);\n "},{"name":"page204.m","page":204,"code":"for ii=1:4\nx1 = 0; x2 = 1; t1 = 0; t2 = 1;\nM=10*2^(ii-1);\nN=M^2;\nh = (x2-x1)/M; dt = (t2-t1)/N;\ns =dt /h;\nx = x1:h:x2; x = x';\nt = t1:dt:t2; t = t';\nu = zeros(M+1,N+1);\nu(1,:)=exp(t);\nu(M+1,:)=exp(1+t);\nu(:,1)=exp(x);\nrow1 = zeros(M-1,1); \nrow1(1,1) = -2; row1(2,1) = 1;\nA = toeplitz(row1);\nrow2 = sparse(M-1,1); \nrow2(1,1) = 10; row2(2,1) = 1;\nB = toeplitz(row2);\n\nH1 = sparse(M-1,1);\nH1(1,1) =  - 2/12*(u(1,2) - u(1,1))+ s^2/2*(u(1,2) + u(1,1))+ 2/12*dt*exp(x(1));\nH1(M-1,1) = - 2/12*(u(M+1,2) - u(M+1,1))+ s^2/2*(u(M+1,2) + u(M+1,1))+ 2/12*dt*exp(x(M+1));\n           \nu(2:M,2) =  (2/12*B-s^2/2*A)\\(2/12*B*u(2:M,1)+H1+2/12*dt*B*exp(x(2:M))+ s^2/2*A*u(2:M,1));\n\nfor k = 2:N\n    H5 = sparse(M-1,1);\n    H5(1,1) = -1/12*u(1,k+1)+ s^2/2*u(1,k+1) + s^2/2*u(1,k-1)+ 1/6*u(1,k)-1/12*u(1,k-1);\n    H5(M-1,1) = -1/12*u(M+1,k+1)+ s^2/2*u(M+1,k+1) + s^2/2*u(M+1,k-1)+ 2/12*u(M+1,k)-1/12*u(M+1,k-1);\n    u(2:M,k+1) = (1/12*B-s^2/2*A)\\(s^2/2*A*u(2:M,k-1) + H5 + 2/12*B*u(2:M,k) - 1/12*B*u(2:M,k-1));\nend\n% 计算误差\nF = zeros(M+1, N+1);\nfor i = 1:M+1\n    for j = 1:N+1\n        F(i, j) =exp(x(i)+t(j));\n    end\nend\nerror = abs(u-F);\nMaxErr(ii) = max(max(error));\ndisp( MaxErr(ii));\nfigure(1)\nhold on\nplot(x,abs(u(:,1+N)-F(:,1+N)))\nend\nfor j=1:3\nOrd = (MaxErr(j)/MaxErr(j+1));\ndisp(['收敛阶为：',num2str(Ord)])\nend\nfigure(2)\nplot(x,u(:,1+N));\nfigure(3)\nplot(x,F(:,1+N));\n    [X, T] = meshgrid(x, t);\nerror = error';\n    figure(4)\n    mesh(X, T, error);\n "}],"topics":[{"name":"二维抛物方程","desc":"二维热传导方程的差分格式与网格加密实验。","files":["page180.m","page197.m","page204.m"]}]},{"id":"ch5","name":"第五章","files":[{"name":"a253.m","page":null,"code":"for ii=1:6\n    xa=0;xb=1;ya=0;yb=1;ta=0;tb=1;\n     M=10*2^(ii-1);\n    N=10*2^(ii-2);\n    dt=(tb-ta)/2*N;\n    h=(xb-xa)/M;\n    x=xa:h:xb;x=x';\n    y=ya:h:yb;y=y';\n    t=ta:dt:tb;t=t';\n    u=zeros(M+1,M+1,2*N+1);\n    for i=1:M+1\n        for j=1:M+1\n            for k=1:2*N+1\n    u(i,j,1)=exp(1/2*(x(i)+y(j)));\n    u(1,j,k)=exp(1/2*y(j)-t(k));u(M+1,j,k)=exp(1/2*(1+y(j))-t(k));\n    u(i,1,k)=exp(1/2*x(i)-t(k));u(i,M+1,k)=exp(1/2*(1+x(i))-t(k));\n            end\n        end\n    end\n    a=1;\nr=a*dt/h^2;  \n I=eye(M-1);\n  B1=(1+r)*I;\nC1=(-r/2)*I; \nO=zeros(M-1);\nA1 = kron(diag(ones(1,M-2),1) + diag(ones(1,M-2),-1),C1)+ kron(diag(ones(1,M-1)),B1);                     \n                     \nrow1=zeros(M-1,1);\nrow1(1,1)=1-r;row1(2,1)=r/2;\nB2=toeplitz(row1);\n  A2 = kron(diag(ones(1,M-2),1) + diag(ones(1,M-2),-1),O)+ kron(diag(ones(1,M-1)),B2);                 \nrow2=zeros(M-1,1);\nrow2(1,1)=1+r;row2(2,1)=-r/2;\nB3=toeplitz(row2);\n\n A3 = kron(diag(ones(1,M-2),1) + diag(ones(1,M-2),-1),O)+ kron(diag(ones(1,M-1)),B3);\nB4=(1-r)*I;\n\nC4=r/2*I;\n\nA4 = kron(diag(ones(1,M-2),1) + diag(ones(1,M-2),-1),C4)+ kron(diag(ones(1,M-1)),B4);\nfor k=1:N\nFhalf1=zeros(M-1,M-1);\nFhalf1(1,1:M-1)=u(1,2:M,2*k);\nFhalf1(M-1,1:M-1)=u(M+1,2:M,2*k);\nF1=reshape(Fhalf1,(M-1)*(M-1),1);\nFk=zeros(M-1,M-1);\nFk(1:M-1,1)=u(2:M,1,2*k+1);\nFk(1:M-1,M-1)=u(2:M,M+1,2*k+1);\nu(2:M,2:M,2*k)=A1/(A2*u(2:M,2:M,2*k-1)+r/2*Fhalf1+r/2*Fk);\nu(2:M,2:M,2*k+1)=A3/(A4*u(2:M,2:M,2*k)+r/2*Fhalf1+r/2*Fk);\nend\nF=zeros(M+1,M+1,N+1);\nfor i=1:M+1\n  for  j=1:M+1\n      for k=1:2*N+1\n    F(i,j,k)=exp(1/2*(x(i))+y(j))-t(k);\nend\n  end\n      end\nerror = abs(F-u);\nMaxErr(i) = max(max(error));\nend\nfigure(1)\nmesh(x,y,error(1:m+1,1:n+1));\nfigure(2)\nmesh(x,y,F(1:m+1,1:n+1));\ndisp(MaxErr)\nfor i=1:3\nord=MaxErr(i)/MaxErr(i+1);\ndisp(ord);\nend\n\n\n"},{"name":"ADI.m","page":null,"code":"function U3 = ADI(M,N,h,c,x,y,t)\n%***************************************************************\n% 求解二维抛物型奇次方程 ut=uxx+uyy;\n% 0≤x≤1 ,0≤y≤1 , 0≤t≤T;\n% 该问题的定解: u(x,y,t)=exp( 1/2(x+y)-t);\n% 初值条件: u(x,y,0)=exp( 1/2(x+y) );\n% 边值条件: u(0,y,t)=exp( 1/2*(y)-t ); u(1,y,t)=exp( 1/2*(1+y)-t );\n%  u(x,0,t)=exp( 1/2*x-t ); u(x,1,t)=exp( 1/2*(x+1)-t );\n%***************************************************************\nfor ii=1:4\n    M=10*2^(ii-1);\n    N=M;\nxa=0;xb=1;ya=0;yb=1;ta=0;tb=1;\n    h=(tb-ta)/N;\n    c=(xb-xa)/M;\n    x=xa:c:xb;x=x';\n    y=ya:c:yb;y=y';\n    t=ta:h:tb;t=t';\n    \nr=c./h^2;  \n%构造B1\nbb1=zeros(1,M-1);                          %给主对角线位置赋值.\nfor i=1:M-1\n    bb1(i)=1+r;\nend\nB1=diag(bb1); \n%构造C1\ncc1=zeros(1,M-1);                          %给主对角线位置赋值.\nfor i=1:M-1\n    cc1(i)=-r./2;\nend\nC1=diag(cc1); \n%***************************************************************\n%构造A1\naa1=blkdiag(kron(eye(M-1),B1));             %创建主对角矩阵块\nmid=mat2cell(aa1,(M-1)*ones(1,M-1),(M-1)*ones(1,M-1));\nmid(find(diag(ones(1,M-2),1)==1))={C1};     %创建上对角矩阵块\nmid(find(diag(ones(1,M-2),-1)==1))={C1};    %创建下对角矩阵块\nA1=cell2mat(mid);                        \n%***************************************************************\n%构造B2\nbb1=zeros(1,M-2);                     \nfor i=1:M-2                            %给-1,1对角线位置赋值.\n    bb1(i)=r./2;\nend\nbb2=zeros(1,M-1);                          %给主对角线位置赋值.\nfor i=1:M-1\n    bb2(i)=1-r;\nend\nB2=diag(bb1,-1)+diag(bb2)+diag(bb1,1);    \n%***************************************************************\n%构造A2\naa2=blkdiag(kron(eye(M-1),B2));           %创建主对角矩阵块\nmid=mat2cell(aa2,(M-1)*ones(1,M-1),(M-1)*ones(1,M-1));\nA2=cell2mat(mid);                        \n%***************************************************************\n%构造B3\nbb4=zeros(1,M-2);                     \nfor i=1:M-2                            %给-1,1对角线位置赋值.\n    bb4(i)=-r./2;\nend\nbb5=zeros(1,M-1);                       %给主对角线位置赋值.\nfor i=1:M-1\n    bb5(i)=1+r;\nend\nB3=diag(bb4,-1)+diag(bb5)+diag(bb4,1);    \n%***************************************************************\n%构造A3\naa3=blkdiag(kron(eye(M-1),B3));           %创建主对角矩阵块\nmid=mat2cell(aa3,(M-1)*ones(1,M-1),(M-1)*ones(1,M-1));\nA3=cell2mat(mid);        \n%***************************************************************\n%构造B4\nbb6=zeros(1,M-1);                          %给主对角线位置赋值.\nfor i=1:M-1\n    bb6(i)=1-r;\nend\nB4=diag(bb6);\n%***************************************************************\n%构造C4\ncc=zeros(1,M-1);                          %给主对角线位置赋值.\nfor i=1:M-1\n    cc(i)=r./2;\nend\nC4=diag(cc);\n%***************************************************************\n%构造A4\naa4=blkdiag(kron(eye(M-1),B4));             %创建主对角矩阵块\nmid=mat2cell(aa4,(M-1)*ones(1,M-1),(M-1)*ones(1,M-1));\nmid(find(diag(ones(1,M-2),1)==1))={C4};     %创建上对角矩阵块\nmid(find(diag(ones(1,M-2),-1)==1))={C4};    %创建下对角矩阵块\nA4=cell2mat(mid);\n%***************************************************************\n%Fk+1/2, 先构造f1\nff1=zeros(1,M-2);                     \nfor i=1:M-2                            %给-1,1对角线位置赋值.\n    ff1(i)=r./4;\nend\nff2=zeros(1,M-1);                        %给主对角线位置赋值.\nfor i=1:M-1\n    ff2(i)=(1-r)./2;\nend\nf1=diag(ff1,-1)+diag(ff2)+diag(ff1,1);    \n%***************************************************************\n%再构造f2\nff1=zeros(1,M-2);                     \nfor i=1:M-2                            %给-1,1对角线位置赋值.\n    ff1(i)=-r./4;\nend\nff2=zeros(1,M-1);                          %给主对角线位置赋值.\nfor i=1:M-1\n    ff2(i)=(1+r)./2;\nend\nf2=diag(ff1,-1)+diag(ff2)+diag(ff1,1);    \n%***************************************************************\nU0=zeros((M-1)*(M-1),1);\ncount1=1;%记录第0层总个数\n% 初值条件如下，给第0层赋值\nfor i=1:M-1    %不包括边界值\n    for j=1:M-1\n       U0(count1,1)=exp(0.5*(x(i+1)+y(j+1))-t(1));\n       count1=count1+1;\n    end\nend\n%***************************************************************\n%先求k+1/2层\nk=1;%记录行数\nFF1=zeros(M-1,1);\nFF2=zeros(M-1,1);\nuk=zeros(M-1,1);%u(0,j,k)|u(M,j,k)\nuk1=zeros(M-1,1);%u(0,j,k+1)|u(M,j,k+1)\nuk_1=zeros(M-1,1);%u(0,0/M,k)|u(M,0/M,k)\nuk1_1=zeros(M-1,1);%u(0,0/M,k+1)|u(M,0/M,k+1)\nF1=zeros((M-1)*(M-1),1);\nwhile k~=N+1\n%***************************************************************\n%构造F(k+1/2)\n%FF1\nfor i=1:M-1\n    uk(i,1)=exp(0.5*(y(i+1)-t(k)));\n    uk1(i,1)=exp(0.5*(y(i+1)-t(k+1)));\nend\nuk_1(1,1)=exp(1*t(k));\nuk_1(M-1,1)=exp(0.5-t(k));\nuk1_1(1,1)=exp(t(k+1));\nuk1_1(M-1,1)=exp(0.5+t(k+1));\nFF1=f1*uk+r./4*uk_1+f2*uk1-r./4*uk1_1;\n%***************************************************************\n%FF2\nfor i=1:M-1\n    uk(i,1)=exp(0.5*(1+y(i+1)+t(k)));\n    uk1(i,1)=exp(0.5*(1+y(i+1)+t(k+1)));\nend\nuk_1(1,1)=exp(0.5+t(k));\nuk_1(M-1,1)=exp(1+t(k));\nuk1_1(1,1)=exp(0.5+t(k+1));\nuk1_1(M-1,1)=exp(1+t(k+1));\nFF2=f1*uk+r./4*uk_1+f2*uk1-r./4*uk1_1;\n% 在下面把FF1全部赋给F1即F(k+1/2)向量的前M-1项\nfor j=1:M-1    \n F1(j,1)=FF1(j,1);\nend\n% 在下面把FF2全部赋给F1即F(k+1/2)向量的最后的M-1项\npp=1;\nfor j=(M-1)*(M-2)+1:(M-1)*(M-1)\n F1(j,1)=FF2(pp,1);  %Fk+1/2\n pp=pp+1;\nend\n%***************************************************************\n% 构造F(k)\nF=zeros((M-1)*(M-1),1);%Fk\nc=1;\nfor j=1:M-1\n    F(c,1)=exp(0.5*(x(j+1)+t(k)));\n    F(c+M-2,1)=exp(0.5*(1+x(j+1)+t(k)));\n    c=c+M-1;\nend\nf=A2*U0+0.5.*r*F1+0.5.*r*F;\nU1=A1\\f;      %U1为第一阶段利用U(k)所求的U(k+1/2);\n%***************************************************************\n \n% 继续往下求解, 利用U(k+1/2)求的U(k+1), 此为第二阶段\n% U(k+1/2)已存放到U1中, F(k+1/2)已存放到F1之中, 在第二阶段需要使用两者;\nff6=zeros((M-1)*(M-1),1); %Fk+1\n% ff6为所需要的F(k+1);\nc=1;\nfor j=1:M-1\n    ff6(c,1)=exp(0.5*(x(j+1)+t(k+1)));\n    ff6(c+M-2,1)=exp(0.5*(1+x(j+1)+t(k+1)));\n    c=c+M-1;\nend\nFF=A4*U1+0.5*r*(ff6+F1);\nU=A3\\FF;\n%***************************************************************\n% U为所求的U(k+1)\nU0=U; % 把U(k+1)作为下一次迭代的初值条件\nU=reshape(U,M-1,M-1);\nfor i=2:M\n    for j=2:M\n       U3(i,j,k)=U(i-1,j-1); \n    end\nend\nfor i=1:M+1\n U3(i,1,k)=exp(0.5*(x(i))-t(k+1));  %左边界\n U3(i,M+1,k)=exp(0.5*(1+x(i))-t(k+1)); %右边界\nend\n \nfor i=1:M+1\n U3(1,i,k)=exp(0.5*(y(i)-t(k+1)));  %上边界\n U3(M+1,i,k)=exp(0.5*(1+y(i))-t(k+1)); %下边界\nend\n \nk=k+1;  %进入下一层\nend\n    end\n\n"},{"name":"ADIexample.m","page":null,"code":"M=200;%网格数量\nN=2000;%时间分割\nT=0.05;%总时间\nnumber = 50;%初始点数\ntau=T./N;\nL=1;\na=1;%导热系数决定的\nh=L./M;\nr=tau./h./h./2.*a.^2;%网比\ndisp(r);\nH=sparse(diag(ones(1,M)*(2.*r+1)))+sparse(diag(ones(1,M-1)*(-r),1))+sparse(diag(ones(1,M-1)*(-r),-1));\nv=zeros(M,M);\nu=zeros(M,M);%初值\nu(1,:)=0;u(M,:)=0;u(:,1)=0;u(:,M)=0;\n[X,Y] = meshgrid(h:h:L,h:h:L);\nRP = [randperm(M-2,number)'+1,randperm(M-2,number)'+1];%初始温度为100.0的点\nfor iter = 1:number\nu(RP(iter,1),RP(iter,2)) = 100.0;\nend\nfor k = 2:N\nu(1,:)=0;u(M,:)=0;u(:,1)=0;u(:,M)=0;\ndelta_y=([zeros(M,1),u(:,1:M-1)]+[u(:,2:M),zeros(M,1)]-2*u)*r;\nv=H\\(u+delta_y);\nv=v';\ndelta_x=([zeros(M,1),v(:,1:M-1)]+[v(:,2:M),zeros(M,1)]-2*v)*r;\nu=H\\(v+delta_x);\nu=u';\nu(1,:)=0;u(M,:)=0;u(:,1)=0;u(:,M)=0;\ncolormap(hot(10));\n    contourf(h:h:L, (h:h:L)', u, 'ShowText','on');\n    colorbar\n    title('热传导初边值问题');\n    hold off;\n     frame=getframe(gcf);\n    imind=frame2im(frame); [imind,cm] = rgb2ind(imind,256);\n    if k==1\n       imwrite(imind,cm,'test.gif','gif', 'Loopcount',inf,'DelayTime',1e-4);\n    else\n        if mod(k,100)==1\n       imwrite(imind,cm,'test.gif','gif','WriteMode','append','DelayTime',1e-4);\n       fprintf('epoch=%d\\n',k);\n        end\n    end\nend\n"},{"name":"chase.m","page":null,"code":"function [x] = chase(A,d)\nb=[0;diag(tril(A,-1),-1)];%下对角线  tril(A,-1)仅提取主对角线下方的元素。\na=diag(A);%中对角线\nc=[diag(triu(A,1),1);0];%上对角线\nl=zeros(size(b,1),1);%求L size(a,1)仅查询 a 的第1个维度的长度\nu=zeros(size(a,1),1);%求U\nn=size(a,1);%矩阵的维度\nx=zeros(n,1);\ny=zeros(n,1);\nu(1)=a(1);\nfor i=2:n\n    l(i)=b(i)/u(i-1);\n    u(i)=a(i)-l(i)*c(i-1);\nend\ny(1)=d(1);\nfor i=2:n\n    y(i)=d(i)-l(i)*y(i-1);\nend\nx(n)=y(n)/u(n);\nfor i=n-1:-1:1\n    x(i)=(y(i)-c(i)*x(i+1))/u(i);\nend\nend\n\n"},{"name":"CN.m","page":null,"code":"for ii=1:4\n    x1 = 0; x2 = 1; y1 = 0; y2 = 1; t1 = 0; t2 = 1; \n    s = 0.1;\n    m1 = (10* 2^(ii-1));\n    m2 = m1;\n    n = m1;\n    h1 = (x2 - x1) / m1; \n    h2 = h1;\n    dt = (t2 - t1) / n;\n    x = x1:h1:x2; x = x';\n    y = y1:h2:y2; y = y';\n    t = t1:dt:t2; t = t';\n    G = @(x, y, t)-3/2*exp((x+y)/2-t);\n    u = zeros(m1+1, m2+1, n+1);\n    for i = 1:m1+1\n        for k=1:n+1\n            u(i, 1, k) =exp(x(i)/2-t(k));\n            u(i, m2+1,k) =exp((x(i)+1)/2-t(k));\n        end\n    end\n    for j = 1:m1+1\n        for k=1:n+1\n            u(1, j, k) =exp(y(j)/2-t(k));\n            u(m1+1, j,k)=exp((1+y(j))/2-t(k));\n        end\n    end\n    for i = 1:m1+1\n        for j = 1:m2+1\n            \n                u(i, j, 1) = exp((x(i)+y(j))/2);\n            end\n        end\n   \n    a = 1;\n    r1 = a * dt / (h1^2);\n    r2 = a * dt / (h2^2);\n    I = speye(m1-1, m1-1);\n    D = -r2/2 * I;\n    row2 = zeros(m1-1, 1);\n    row2(1, 1) =1 +(r1 + r2);\n    row2(2, 1) = -r1/2;\n    C = toeplitz(row2);\n    A = kron(diag(ones(1, m2-2), 1) + diag(ones(1, m2-2), -1), D) + kron(diag(ones(1, m2-1)), C);\n\n    for k = 1:n\n        t_khalf=(t(k)+t(k+1))/2;\n        H = zeros(m1-1, m2-1);  \n        for i=2:m1-2\n        for j = 2:m2\n            H(i, j-1) = r1/2*u(i,j,k)+(1-r1-r2)*u(i+1,j,k)+r1/2*u(i+2,j,k)+r2/2*u(i+1,j-1,k)+r2/2*u(i+1,j+1,k)+dt*G(x(i+1),y(j),t_khalf);\n              H(1, j-1) =r1/2*u(1,j,k)+(1-r1-r2)*u(2,j,k)+r1/2*u(3,j,k)+r2/2*u(2,j-1,k)+r2/2*u(2,j+1,k)+dt*G(x(2),y(j),t_khalf)+r1/2*u(1,j,k+1);\n               H(m1-1, j-1) = r1/2*u(m1-1,j,k)+(1-r1-r2)*u(m1,j,k)+r1/2*u(m1+1,j,k)+r2/2*u(m1,j-1,k)+r2/2*u(m1,j+1,k)+dt*G(x(m1),y(j),t_khalf)+r1/2*u(m1+1,j,k+1);\n        end\n        end\n      \n        H(:, 1) = H(:, 1) - D * u(2:m1, 1, k+1);\n        H(:, m2-1) = H(:, m2-1) - D * u(2:m1, m2+1, k+1);  \n\n        F = reshape(H, (m1-1) * (m2-1), 1);\n\n        U1 =A\\F;\nU2=reshape(U1, m1-1, m2-1);\n        u(2:m1, 2:m2, k+1) = U2;\n    end\n    F = zeros(m1+1, m2+1, n+1);\n    for i = 1:m1+1\n        for j = 1:m2+1\n            for k = 1:n+1\n                F(i, j, k) = exp((x(i)+y(j))/2-t(k));\n            end\n        end\n    end\n\n    error = abs(u - F);\n    MaxErr(ii) = max(max(max(error)));\nend\n\ndisp(MaxErr);\nfor i = 1:3\n    ord(i) = MaxErr(i) / MaxErr(i+1);\nend\n\ndisp(ord);"},{"name":"page236douglas.m","page":236,"code":"tic\nfor ii=1:4\nm1=10*2^(ii-1);\nm2=10*2^(ii-1);\nn=10*2^(ii-1);\nxa = 0; xb = 1; ya = 0; yb = 1; ta = 0; tb = 1;\nh1 = (xb-xa)/m1;h2=(yb-ya)/m2;dt = (tb-ta)/n;\nx = xa:h1:xb;  x = x'; y = ya:h2:yb;  y = y';\nt = ta:dt:tb; t = t';\na=1;\nr1 = a*dt/h1^2;\nr2 = a*dt/h2^2;\nu = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        u(i,j,1) = exp(1/2*(x(i)+y(j)));\n    end\nend\nfor j = 1:m2+1\n    for k = 1:n+1\n        u(1,j,k) = exp(1/2*y(j)-t(k));\n        u(m2+1,j,k) = exp(1/2*(1+y(j))-t(k));\n    end\nend\nfor i = 1:m1+1\n    for k = 1:n+1\n        u(i,1,k) = exp(1/2*x(i)-t(k));\n        u(i,m2+1,k) = exp(1/2*(1+x(i))-t(k));\n    end\nend\nff5 = @(x,y,t) -3/2*exp(1/2*(x+y)-t);\n\nfor k = 1:n\n    u1 = zeros(m1+1,m2+1);  \n    for j = 2:m2\n        u1(1,j)   = -r2/2*(u(1,j-1,k+1)+u(1,j+1,k+1)-u(1,j-1,k)-u(1,j+1,k))+(1+r2)*(u(1,j,k+1)-u(1,j,k));\n        u1(m1+1,j) = -r2/2*(u(m1+1,j-1,k+1)+u(m1+1,j+1,k+1)-u(m1+1,j-1,k)-u(m1+1,j+1,k))+(1+r2)*(u(m1+1,j,k+1)-u(m1+1,j,k));\n        H = zeros(m1-1,1);\n        H(1,1)   = 1/2*r1*u1(1,j);\n        H(m1-1,1) = 1/2*r1*u1(m1+1,j);\n       row1 = zeros(m2-1, 1);\n      row1(2, 1) = -1/2*r1;row1(1, 1) = 1+r1; \n      A = toeplitz(row1);\n        u1(2:m1,j) = chase(A,(r1*(u(1:m1-1,j,k)-2*u(2:m1,j,k)+u(3:m1+1,j,k))+r2*(u(2:m1,j-1,k)-2*u(2:m1,j,k)+u(2:m1,j+1,k))+dt*ff5(x(2:m1),y(j),(t(k+1)+t(k))/2)+H));\n    end\n    for i = 2:m1\n        u(i,1,k+1) = exp(1/2*x(i)-t(k+1));\n        u(i,m2+1,k+1) = exp(1/2*(1+x(i))-t(k+1));\n        H1 = zeros(m2-1,1);\n        H1(1,1)   = 1/2*r2*u(i,1,k+1);\n        H1(m2-1,1) = 1/2*r2*u(i,m2+1,k+1);\n        H2 = zeros(m2-1,1);\n        H2(1:m2-1)=(1+r2)*u(i,2:m2,k)-1/2*r2*u(i,1:m2-1,k)-1/2*r2*u(i,3:m2+1,k);\n        H3 = zeros(m2-1,1);\n        H3(1:m2-1)=u1(i,2:m2);\n         row2 = zeros(m2-1, 1);\n      row2(2, 1) = -1/2*r2;row2(1, 1) = 1+r2; \n      B = toeplitz(row2);\n        u(i,2:m2,k+1) = chase(B,(H3+H2+H1));\n    end\nend\nF = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        for k = 1:n+1\n            F(i,j,k) = exp(1/2*(x(i)+y(j))-t(k));\n        end\n    end\nend\nerror = abs(F-u);\nfigure(3)\n    mesh(x(2:m1),y(2:m2),error(2:m1,2:m2,n+1))\n    hold on\nMaxErr(ii)=max(max(max(error)));\ndisp(MaxErr(ii));\nend\nfor i=1:3\nord=MaxErr(i)/MaxErr(i+1);\ndisp(['收敛阶为',num2str(ord)]);\nend\n    figure(1)\n    mesh(x, y, F(:, :, n+1));\n    figure(2)\n    mesh(x, y, u(:, :, n+1));\n    elapsedTime = toc;\n\n% 输出计时结果\ndisp(['程序运行时间为：', num2str(elapsedTime), '秒']);\n    \n    "},{"name":"page236DY.m","page":236,"code":"tic\nfor ii=1:4\nm1=10*2^(ii-1);\nm2=10*2^(ii-1);\nn=10*2^(ii-1);\nxa = 0; xb = 1; ya = 0; yb = 1; ta = 0; tb = 1;\nh1 = (xb-xa)/m1;h2=(yb-ya)/m2;dt = (tb-ta)/n;\nx = xa:h1:xb;  x = x'; y = ya:h2:yb;  y = y';\nt = ta:dt:tb; t = t';\nr1 = dt/h1^2;\nr2 = dt/h2^2;\nu = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        u(i,j,1) = exp(1/2*(x(i)+y(j)));\n    end\nend\nfor j = 1:m2+1\n    for k = 1:n+1\n        u(1,j,k) = exp(1/2*y(j)-t(k));\n        u(m2+1,j,k) = exp(1/2*(1+y(j))-t(k));\n    end\nend\nfor i = 1:m1+1\n    for k = 1:n+1\n        u(i,1,k) = exp(1/2*x(i)-t(k));\n        u(i,m2+1,k) = exp(1/2*(1+x(i))-t(k));\n    end\nend\nff5 = @(x,y,t) -3/2*exp(1/2*(x+y)-t);\n\nfor k = 1:n\n    u1 = zeros(m1+1,m2+1);  \n    for j = 2:m2\n        H = zeros(m1-1,1);\n        u1(1,j)   = u(1,j,k+1)-1/2*r2*(u(1,j-1,k+1)-2*u(1,j,k+1)+u(1,j+1,k+1));\n        u1(m1+1,j) = u(m1+1,j,k+1)-1/2*r2*(u(m1+1,j-1,k+1)-2*u(m1+1,j,k+1)+u(m1+1,j+1,k+1));\n        H(1,1)   = 1/2*r1*u1(1,j);\n        H(m1-1,1) = 1/2*r1*u1(m1+1,j);\n       \n       row1 = zeros(m2-1, 1);\n      row1(2, 1) = -1/2*r1;row1(1, 1) = 1+r1; \n      A = toeplitz(row1);\n        u1(2:m1,j) = chase(A,(u(2:m1,j,k)+1/2*r1*(u(1:m1-1,j,k)-2*u(2:m1,j,k)+u(3:m1+1,j,k))+1/2*r1*(u(2:m1,j-1,k)-2*u(2:m1,j,k)+u(2:m1,j+1,k))+ ...\n            dt*(ff5(x(2:m1),y(j),t(k))+ff5(x(2:m1),y(j),t(k+1)))/2+1/4*r1*r2*((u(1:m1-1,j-1,k)-2*u(1:m1-1,j,k)+u(1:m1-1,j+1,k))...\n            -2*(u(2:m1,j-1,k)-2*u(2:m1,j,k)+u(2:m1,j+1,k))+...\n            (u(3:m1+1,j-1,k) -2*u(3:m1+1,j,k) +u(3:m1+1,j+1,k)) )+H));\n    end\n    for i = 2:m1\n        H1 = zeros(m1-1,1);\n        H1(1:m2-1) = u1(i,2:m2);\n        H2 = zeros(m1-1,1);\n        H2(1,1)   = 1/2*r1*u(i,1,k+1);\n        H2(m1-1,1) = 1/2*r1*u(i,m2+1,k+1);\n         row2 = zeros(m2-1, 1);\n      row2(2, 1) = -1/2*r1;row2(1, 1) = 1+r1; \n      B = toeplitz(row1);\n        u(i,2:m2,k+1) = chase(B,(H1+H2));\n    end\nend\nF = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        for k = 1:n+1\n            F(i,j,k) = exp(1/2*(x(i)+y(j))-t(k));\n        end\n    end\nend\nerror = abs(F-u);\nfigure(3)\n    mesh(x(2:m1),y(2:m2),error(2:m1,2:m2,n+1))\n    hold on\n    \nMaxErr(ii)=max(max(max(error)));\ndisp(MaxErr(ii));\nend\nfor i=1:3\nord=MaxErr(i)/MaxErr(i+1);\ndisp(['收敛阶为',num2str(ord)]);\nend\n    figure(1)\n    mesh(x, y, F(:, :, n+1));\n    figure(2)\n    mesh(x, y, u(:, :, n+1));\n    elapsedTime = toc;\n\n% 输出计时结果\ndisp(['程序运行时间为：', num2str(elapsedTime), '秒']);\n    "},{"name":"page236PR.m","page":236,"code":"tic\nfor ii=1:4\nm1=10*2^(ii-1);\nm2=10*2^(ii-1);\nn=10*2^(ii-1);\nxa = 0; xb = 1; ya = 0; yb = 1; ta = 0; tb = 1;\nh1 = (xb-xa)/m1;h2=(yb-ya)/m2;dt = (tb-ta)/n;\nx = xa:h1:xb;  x = x'; y = ya:h2:yb;  y = y';\nt = ta:dt:tb; t = t';\na=1;\nr1 = a*dt/h1^2;\nr2 = a*dt/h2^2;\nu = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        u(i,j,1) = exp(1/2*(x(i)+y(j)));\n    end\nend\nfor j = 1:m2+1\n    for k = 1:n+1\n        u(1,j,k) = exp(1/2*y(j)-t(k));\n        u(m2+1,j,k) = exp(1/2*(1+y(j))-t(k));\n    end\nend\nfor i = 1:m1+1\n    for k = 1:n+1\n        u(i,1,k) = exp(1/2*x(i)-t(k));\n        u(i,m2+1,k) = exp(1/2*(1+x(i))-t(k));\n    end\nend\nff5 = @(x,y,t) -3/2*exp(1/2*(x+y)-t);\n\nfor k = 1:n\n    u1 = zeros(m1+1,m2+1);  \n    for j = 2:m2\n        u1(1,j)   = (1-r2)/2*u(1,j,k)+(1+r2)/2*u(1,j,k+1)+r2/4*(u(1,j-1,k)+u(1,j+1,k)-u(1,j-1,k+1)-u(1,j+1,k+1));\n        u1(m1+1,j) = (1-r2)/2*u(m1+1,j,k)+(1+r2)/2*u(m1+1,j,k+1)+r2/4*(u(m1+1,j-1,k)+u(m1+1,j+1,k)-u(m1+1,j-1,k+1)-u(m1+1,j+1,k+1));\n        H = zeros(m1-1,1);\n        H(1,1)   = 1/2*r1*u1(1,j);\n        H(m1-1,1) = 1/2*r1*u1(m1+1,j);\n       row1 = zeros(m2-1, 1);\n      row1(2, 1) = -1/2*r1;row1(1, 1) = 1+r1; \n      A = toeplitz(row1);\n        u1(2:m1,j) = chase(A,((1-r2)*u(2:m1,j,k)+1/2*r2*u(2:m1,j+1,k)+1/2*r2*u(2:m1,j-1,k)+dt/2*(ff5(x(2:m1),y(j),t(k))+ff5(x(2:m1),y(j),t(k+1)))/2+H));\n    end\n    for i = 2:m1\n        u(i,1,k+1) = exp(1/2*x(i)-t(k+1));\n        u(i,m2+1,k+1) = exp(1/2*(1+x(i))-t(k+1));\n        H1 = zeros(m2-1,1);\n        H1(1,1)   = 1/2*r2*u(i,1,k+1);\n        H1(m2-1,1) = 1/2*r2*u(i,m2+1,k+1);\n        H2 = zeros(m2-1,1);\n        H2(1:m2-1)=(1-r1)*u1(i,2:m2)+1/2*r1*u1(i+1,2:m2)+1/2*r1*u1(i-1,2:m2);\n         row2 = zeros(m2-1, 1);\n      row2(2, 1) = -1/2*r2;row2(1, 1) = 1+r2; \n      B = toeplitz(row2);\n        u(i,2:m2,k+1) = chase(B,(H2+H1+dt/2*((ff5(x(i),y(2:m2),t(k))+ff5(x(i),y(2:m2),t(k+1)))/2)));\n    end\nend\nF = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        for k = 1:n+1\n            F(i,j,k) = exp(1/2*(x(i)+y(j))-t(k));\n        end\n    end\nend\nerror = abs(F-u);\nfigure(3)\n    mesh(x(2:m1),y(2:m2),error(2:m1,2:m2,n+1))\n    hold on\nMaxErr(ii)=max(max(max(error)));\ndisp(MaxErr(ii));\nend\nfor i=1:3\nord=MaxErr(i)/MaxErr(i+1);\ndisp(['收敛阶为',num2str(ord)]);\nend\n    figure(1)\n    mesh(x, y, F(:, :, n+1));\n    figure(2)\n    mesh(x, y, u(:, :, n+1));\n    elapsedTime = toc;\n\n% 输出计时结果\ndisp(['程序运行时间为：', num2str(elapsedTime), '秒']);\n    "},{"name":"page236two.m","page":236,"code":"for ii=1:5\n     xa=0;xb=1;ya=0;yb=1;ta=0;tb=1;\n     m1=10*2^(ii-1);\n     m2=10*2^(ii-1);\n    n=10*2^(ii-1);\n    h1=(xb-xa)/m1;\n    h2=(tb-ta)/n;\nx=(0:m1)*h1+0;\ny=(0:m2)*h1+0;\nt=(0:n)*h2+0;t0=(0:n)*h2+1/2*h2;\nfor k=1:n+1\n    for i=1:m2+1\n        for j=1:m1+1\n            f(i,j,k)=-3/2*exp(1/2*(x(j)+y(i))-t0(k)); \n    \n        end\n    end\nend\n\nfor i=1:m2+1\n    for j=1:m1+1\n    u(i,j,1)=exp(1/2*(x(j)+y(i)));\n    end\nend\n\nfor k=1:n+1\n    for i=1:m2+1\n        u(i,[1 m1+1],k)=[exp(1/2*y(i)-t(k)) exp(1/2*(1+y(i))-t(k))];\n    end\nend\nr=h2/(h1*h1);r4=1+r;r5=r/2;\nfor k=1:n\n    for i=2:m2\n        u0(i,[1 m1+1],k)=r4*u(i,[1 m1+1],k+1)-r5*(u(i-1,[1 m1+1],...\n            k+1)+u(i+1,[1 m1+1],k+1));  \n    end\nend\nfor k=1:n+1\n    for j=1:m1+1\n        u([1 m2+1],j,k)=[exp(1/2*x(j)-t(k)) exp(1/2*(1+x(j))-t(k))];\n    end\nend\nr1=r-r*r;r2=2*(r-1)*(r-1);r3=r*r/2;\nfor k=1:n  \n    for i=2:m2 \n        a=-r*ones(1,m1-1);\n        c=a;a(1)=0;c(m1-1)=0;\n        b=2*r4*ones(1,m1-1);\n        d(1)=r*u0(i,1,k)+r1*(u(i-1,2,k)+u(i,1,k)+u(i+1,2,k)+...\n            u(i,3,k))+r2*u(i,2,k)+r3*(u(i-1,1,k)+...\n            u(i+1,1,k)+u(i-1,3,k)+u(i+1,3,k))+2*h2*f(i,2,k);\n        for l=2:m1-2\n            d(l)=r1*(u(i-1,l+1,k)+u(i,l,k)+u(i+1,l+1,k)+...\n            u(i,l+2,k))+r2*u(i,l+1,k)+r3*(u(i-1,l,k)+...\n            u(i+1,l,k)+u(i-1,l+2,k)+u(i+1,l+2,k))+2*h2*f(i,l+1,k);\n       \n        end\n        d(m1-1)=r*u0(i,m1+1,k)+r1*(u(i-1,m1,k)+u(i,m1-1,k)+...\n            u(i+1,m1,k)+u(i,m1+1,k))+r2*u(i,m1,k)+...\n            r3*(u(i-1,m1-1,k)+...\n            u(i+1,m1-1,k)+u(i-1,m1+1,k)+u(i+1,m1+1,k))+2*h2*f(i,m1,k);\n        for l=1:m1-2 \n        a(l+1)=-a(l+1)/b(l);\n        b(l+1)=b(l+1)+a(l+1)*c(l);\n        d(l+1)=d(l+1)+a(l+1)*d(l);\n        end\n      \n        u0(i,m1,k)=d(m1-1)/b(m1-1);\n        for l=m1-2:-1:1\n            u0(i,l+1,k)=(d(l)-c(l)*u0(i,l+2,k))/b(l);\n        end     \n    end\n    for j=2:m1\n        a=-r*ones(1,m2-1);\n        c=a;a(1)=0;c(m2-1)=0;\n        b=2*r4*ones(1,m2-1);\n        d(1)=r*u(1,j,k+1)+2*u0(2,j,k);\n        for l=2:m2-2\n            d(l)=2*u0(l+1,j,k);\n       \n        end\n        d(m2-1)=2*u0(m2,j,k)+r*u(m2+1,j,k+1);\n        for l=1:m2-2 \n        a(l+1)=-a(l+1)/b(l);\n        b(l+1)=b(l+1)+a(l+1)*c(l);\n        d(l+1)=d(l+1)+a(l+1)*d(l);\n        end\n        u(m2,j,k+1)=d(m2-1)/b(m2-1);   \n        for l=m2-2:-1:1\n            u(l+1,j,k+1)=(d(l)-c(l)*u(l+2,j,k+1))/b(l);\n        end     \n    end\nend\nfor k=1:n+1\n    for i=1:m2+1\n        for j=1:m1+1\n            p(i,j,k)=exp(1/2*(x(j)+y(i))-t(k));   \n            error(i,j,k)=abs(u(i,j,k)-p(i,j,k));    \n        end\n    end\nend\nMaxErr(ii)=max(max(max(error)));\ndisp(MaxErr(ii));\nend\nfor i=1:4\nord=MaxErr(i)/MaxErr(i+1);\ndisp(ord);\nend\nfigure(1)\nmesh(x,y,e(1:m1+1,1:m2+1,n+1));\nfigure(2)\nmesh(x,y,p(1:m1+1,1:m2+1,n+1));\n\nfigure(3)\nmesh(x,y,u(1:m1+1,1:m2+1,n+1));\n\n\n\n\n"},{"name":"page250douglas.m","page":250,"code":"for ii=1:4\nm1=10*2^(ii-1);    \nm2=10*2^(ii-1);\nn=100*4^(ii-1);\nff5 = @(x,y,t) -3/2*exp(1/2*(x+y)-t);\nxa = 0; xb = 1; ya = 0; yb = 1;\nta = 0; tb = 1;\nh1 = (xb-xa)/m1;h2 = (tb-ta)/m1; dt = (tb-ta)/n;\nx = xa:h1:xb;  x = x';\ny = ya:h2:yb;  y = y';\nt = ta:dt:tb; t = t';\nr1 = dt/h1^2;r2 = dt/h2^2;\nu = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        u(i,j,1) = exp(1/2*(x(i)+y(j)));\n    end\nend\nfor j = 1:m2+1\n    for k = 1:n+1\n        u(1,j,k) = exp(1/2*y(j)-t(k));\n        u(m1+1,j,k) = exp(1/2*(1+y(j))-t(k));\n    end\nend\nfor i = 1:m1+1\n    for k = 1:n+1\n        u(i,1,k) = exp(1/2*x(i)-t(k));\n        u(i,m2+1,k) = exp(1/2*(1+x(i))-t(k));\n    end\nend\nfor k = 1:n\n    u1 = zeros(m1+1,m2+1); \n    for j = 2:m2\n        u1(1,j)   =(1/12-1/2*r2)*(u(1,j-1,k+1)-u(1,j-1,k))+(10/12+r2)*(u(1,j,k+1)-u(1,j,k))+(1/12-1/2*r2)*(u(1,j+1,k+1)-u(1,j+1,k));\n        u1(m1+1,j) = (1/12-1/2*r2)*(u(m1+1,j-1,k+1)-u(m1+1,j-1,k))+(10/12+r2)*(u(m1+1,j,k+1)-u(m1+1,j,k))+(1/12-1/2*r2)*(u(m1+1,j+1,k+1)-u(m1+1,j+1,k));\n        H = zeros(m1-1,1);\n        H(1,1)   = -(1/12-1/2*r1)*u1(1,j);\n        H(m1-1,1) = -(1/12-1/2*r1)*u1(m1+1,j);\n        L1=zeros(m1-1,1);\n        L1(1:m1-1)=1/12*r1*(u(1:m1-1,j-1,k)-2*u(2:m1,j-1,k)+u(3:m1+1,j-1,k)+10*(u(1:m1-1,j,k)-2*u(2:m1,j,k)+u(3:m1+1,j,k))+u(1:m1-1,j+1,k)-2*u(2:m1,j+1,k)+u(3:m1+1,j+1,k));\n        L2=zeros(m1-1,1);\n        L2(1:m1-1)=1/12*r2*(u(1:m1-1,j-1,k)-2*u(1:m1-1,j,k)+u(1:m1-1,j+1,k)+10*(u(2:m1,j-1,k)-2*u(2:m1,j,k)+u(2:m1,j+1,k))+u(3:m1+1,j-1,k)-2*u(3:m1+1,j,k)+u(3:m1+1,j+1,k));\n        F1=zeros(m1-1,1);\n        F1(1:m1-1)=ff5(x(1:m1-1),y(j-1),(t(k)+t(k+1))/2)+10*ff5(x(2:m1),y(j-1),(t(k)+t(k+1))/2)+ff5(x(3:m1+1),y(j-1),(t(k)+t(k+1))/2)+...\n        10*(ff5(x(1:m1-1),y(j),(t(k)+t(k+1))/2)+10*ff5(x(2:m1),y(j),(t(k)+t(k+1))/2)+ff5(x(3:m1+1),y(j),(t(k)+t(k+1))/2))+...\n        ff5(x(1:m1-1),y(j+1),(t(k)+t(k+1))/2)+10*ff5(x(2:m1),y(j+1),(t(k)+t(k+1))/2)+ff5(x(3:m1+1),y(j+1),(t(k)+t(k+1))/2);\n        row1=zeros(m1-1,1);\n        row1(1,1)=5/6+r1;row1(2,1)=1/12-1/2*r1;\n        A=toeplitz(row1);\n        u1(2:m1,j) = chase(A,(L1+L2+dt/144*F1+H));\n    end\n        for i = 2:m1\n\n         H1 = zeros(m2-1,1);\n        H1(1:m2-1) = u1(i,2:m2);  \n        H2 = zeros(m2-1,1);\n        H2(1,1)   = -(1/12-1/2*r2)*u(i,1,k+1);\n        H2(m1-1,1) = -(1/12-1/2*r2)*u(i,m2+1,k+1);\n        H3 = zeros(m2-1,1);\n        H3(1:m2-1)=(1/12-1/2*r2)*u(i,1:m2-1,k)+(1/12-1/2*r2)*u(i,3:m2+1,k)+(5/6+r2)*u(i,2:m2,k);\n        row2=zeros(m2-1,1);\n        row2(1,1)=5/6+r2;row2(2,1)=1/12-1/2*r2;\n        B=toeplitz(row2);\n        u(i,2:m2,k+1) = chase(B,(H1+H2+H3));\n        \n    end\nend\nF = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        for k = 1:n+1\n            F(i,j,k) = exp(1/2*(x(i)+y(j))-t(k));\n        end\n    end\nend\nerror = abs(F-u);\nfigure(3)\n    mesh(x(2:m1),y(2:m2),error(2:m1,2:m2,n+1))\n    hold on\n    \nMaxErr(ii)=max(max(max(error)));\ndisp(MaxErr(ii));\nend\nfor i=1:3\nord=MaxErr(i)/MaxErr(i+1);\ndisp(['收敛阶为',num2str(ord)]);\nend\n\n    figure(1)\n    mesh(x, y, F(:, :,n+1));\n    figure(2)\n    mesh(x, y, u(:, :, n+1));\n \n    \n"},{"name":"page250DY.m","page":250,"code":"for ii=1:3\nm1=10*2^(ii-1);    \nm2=10*2^(ii-1);\nn=m1^2;\nff5 = @(x,y,t) -3/2*exp(1/2*(x+y)-t);\nxa = 0; xb = 1; ya = 0; yb = 1;\nta = 0; tb = 1;\nh1 = (xb-xa)/m1;h2 = (tb-ta)/m1; dt = (tb-ta)/n;\nx = xa:h1:xb;  x = x';\ny = ya:h2:yb;  y = y';\nt = ta:dt:tb; t = t';\nr1 = dt/h1^2;r2 = dt/h2^2;\nu = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        u(i,j,1) = exp(1/2*(x(i)+y(j)));\n    end\nend\nfor j = 1:m2+1\n    for k = 1:n+1\n        u(1,j,k) = exp(1/2*y(j)-t(k));\n        u(m1+1,j,k) = exp(1/2*(1+y(j))-t(k));\n    end\nend\nfor i = 1:m1+1\n    for k = 1:n+1\n        u(i,1,k) = exp(1/2*x(i)-t(k));\n        u(i,m2+1,k) = exp(1/2*(1+x(i))-t(k));\n    end\nend\nfor k = 1:n\n    u1 = zeros(m1+1,m2+1); \n    for j = 2:m2\n        u1(1,j)   = u(1,j,k+1)+(1/12-1/2*r1)*(u(1,j-1,k+1)-2*u(1,j,k+1)+u(1,j+1,k+1));\n        u1(m1+1,j) = u(m1+1,j,k+1)+(1/12-1/2*r1)*(u(m1+1,j-1,k+1)-2*u(m1+1,j,k+1)+u(m1+1,j+1,k+1));\n        H = zeros(m1-1,1);\n        H(1,1)   = -(1/12-1/2*r1)*u1(1,j);\n        H(m1-1,1) = -(1/12-1/2*r1)*u1(m1+1,j);\n        row1=zeros(m1-1,1);\n        row1(1,1)=5/6+r1;row1(2,1)=1/12-1/2*r1;\n        A=toeplitz(row1);\n        u1(2:m1,j) = chase(A,(u(2:m1,j,k)+(1/12+1/2*r1)*(u(1:m1-1,j,k)-2*u(2:m1,j,k)+u(3:m1+1,j,k))+ ...\n            (1/12+1/2*r1)*(u(2:m1,j-1,k)-2*u(2:m1,j,k)+u(2:m1,j+1,k))+(1/12+1/2*r1)^2*((u(1:m1-1,j-1,k) -2*u(1:m1-1,j,k) +u(1:m1-1,j+1,k))...\n            -2*(u(2:m1,j-1,k)   -2*u(2:m1,j,k)   +u(2:m1,j+1,k))+ ...\n            (u(3:m1+1,j-1,k) -2*u(3:m1+1,j,k) +u(3:m1+1,j+1,k)))+dt*ff5(x(2:m1),y(j),(t(k)+t(k+1))/2)+1/12*dt*(ff5(x(1:m1-1),y(j),(t(k)+t(k+1))/2)-2*ff5(x(2:m1),...\n            y(j),(t(k)+t(k+1))/2)+ff5(x(3:m1+1),y(j),(t(k)+t(k+1))/2))+1/12*dt*(ff5(x(2:m1),y(j-1),(t(k)+t(k+1))/2)-2*ff5(x(2:m1),...\n            y(j),(t(k)+t(k+1))/2)+ff5(x(2:m1),y(j+1),(t(k)+t(k+1))/2))+1/144*dt*((ff5(x(1:m1-1),y(j-1),(t(k)+t(k+1))/2)- ...\n            2*ff5(x(1:m1-1),y(j),(t(k)+t(k+1))/2) +ff5(x(1:m1-1),y(j+1),(t(k)+t(k+1))/2))- ...\n            2*(ff5(x(2:m1),y(j-1),(t(k)+t(k+1))/2)-   ...\n            2*ff5(x(2:m1),y(j),(t(k)+t(k+1))/2)   +ff5(x(2:m1),y(j+1),(t(k)+t(k+1))/2))+   ...\n            (ff5(x(3:m1+1),y(j-1),(t(k)+t(k+1))/2)- ...\n            2*ff5(x(3:m1+1),y(j),(t(k)+t(k+1))/2) +ff5(x(3:m1+1),y(j+1),(t(k)+t(k+1))/2)))+H));\n    end\n    for i = 2:m1\n        H1 = zeros(m1-1,1);\n        H1(1:m1-1) = u1(i,2:m2);\n        H2 = zeros(m1-1,1);\n        H2(1,1)   = -(1/12-1/2*r1)*u(i,1,k+1);\n        H2(m1-1,1) = -(1/12-1/2*r1)*u(i,m2+1,k+1);\n      row2=zeros(m2-1,1);\n        row2(1,1)=5/6+r2;row2(2,1)=1/12-1/2*r2;\n        B=toeplitz(row2);\n        u(i,2:m2,k+1) = chase(B,(H1+H2)); \n    end\nend\nF = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        for k = 1:n+1\n            F(i,j,k) = exp(1/2*(x(i)+y(j))-t(k));\n        end\n    end\nend\nerror = abs(F-u);\nfigure(3)\n      \n    mesh(x(2:m1),y(2:m2),error(2:m1,2:m2,n+1))\n    hold on\n  \nMaxErr(ii)=max(max(max(error)));\ndisp(MaxErr(ii));\nend\nfor i=1:2\nord=MaxErr(i)/MaxErr(i+1);\ndisp(['收敛阶为',num2str(ord)]);\nend\n\n    figure(1)\n    mesh(x, y, F(:, :,n+1));\n    figure(2)\n    mesh(x, y, u(:, :, n+1))\n    \n    \n"},{"name":"page250PR.m","page":250,"code":"for ii=1:4\nm1=10*2^(ii-1);    \nm2=10*2^(ii-1);\nn=m1^2;\nff5 = @(x,y,t) -3/2*exp(1/2*(x+y)-t);\nxa = 0; xb = 1; ya = 0; yb = 1;\nta = 0; tb = 1;\nh1 = (xb-xa)/m1;h2 = (tb-ta)/m1; dt = (tb-ta)/n;\nx = xa:h1:xb;  x = x';\ny = ya:h2:yb;  y = y';\nt = ta:dt:tb; t = t';\nr1 = dt/h1^2;r2 = dt/h2^2;\nu = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        u(i,j,1) = exp(1/2*(x(i)+y(j)));\n    end\nend\nfor j = 1:m2+1\n    for k = 1:n+1\n        u(1,j,k) = exp(1/2*y(j)-t(k));\n        u(m1+1,j,k) = exp(1/2*(1+y(j))-t(k));\n    end\nend\nfor i = 1:m1+1\n    for k = 1:n+1\n        u(i,1,k) = exp(1/2*x(i)-t(k));\n        u(i,m2+1,k) = exp(1/2*(1+x(i))-t(k));\n    end\nend\nfor k = 1:n\n    u1 = zeros(m1+1,m2+1); \n    for j = 2:m2\n        u1(1,j)   = (1/24)*(u(1,j-1,k+1)+u(1,j-1,k))+5/12*(u(1,j,k+1)+u(1,j,k))+(1/24)*(u(1,j+1,k+1)+u(1,j+1,k))+r2/4*(u(1,j-1,k)-2*u(1,j,k)+u(1,j+1,k)-(u(1,j-1,k+1)-2*u(1,j,k+1)+u(1,j+1,k+1)));\n        u1(m1+1,j) = (1/24)*(u(m1+1,j-1,k+1)+u(m1+1,j-1,k))+5/12*(u(m1+1,j,k+1)+u(m1+1,j,k))+(1/24)*(u(m1+1,j+1,k+1)+u(m1+1,j+1,k))+r2/4*(u(m1+1,j-1,k)-2*u(m1+1,j,k)+u(m1+1,j+1,k)-(u(m1+1,j-1,k+1)-2*u(m1+1,j,k+1)+u(m1+1,j+1,k+1)));\n        H = zeros(m1-1,1);\n        H(1,1)   = -(1/12-1/2*r1)*u1(1,j);\n        H(m1-1,1) = -(1/12-1/2*r1)*u1(m1+1,j);\n        L=zeros(m1-1,1);\n        L(1:m1-1)=(1/12+1/2*r2)*u(2:m1,j-1,k)+(1/12+1/2*r2)*u(2:m1,j+1,k)+(5/6-r2)*u(2:m1,j,k);\n        F1=zeros(m1-1,1);\n        F1(1:m1-1)=1/12*ff5(x(2:m1),y(j-1),(t(k)+t(k+1))/2)+ 5/6*ff5(x(2:m1),y(j),(t(k)+t(k+1))/2)+1/12*ff5(x(2:m1),y(j+1),(t(k)+t(k+1))/2);\n        row1=zeros(m1-1,1);\n        row1(1,1)=5/6+r1;row1(2,1)=1/12-1/2*r1;\n        A=toeplitz(row1);\n        u1(2:m1,j) = chase(A,L+dt/2*F1+H);\n           \n    end   \n    for i = 2:m1\n        u(i,1,k+1) = exp(1/2*x(i)-t(k+1));\n        u(i,m2+1,k+1) = exp(1/2*(1+x(i))-t(k+1));\n        H1 = zeros(m2-1,1);\n        H1(1:m2-1) = (1/12+1/2*r1)*u1(i-1,2:m2)+(1/12+1/2*r1)*u1(i+1,2:m2)+(5/6-r1)*u1(i,2:m2);\n        H2 = zeros(m2-1,1);\n        H2(1,1)   = -(1/12-1/2*r2)*u(i,1,k+1);\n        H2(m1-1,1) = -(1/12-1/2*r2)*u(i,m2+1,k+1);\n        F2=zeros(m2-1,1);\n        F2(1:m2-1)=1/12*ff5(x(i),y(1:m2-1),(t(k)+t(k+1))/2)+ 5/6*ff5(x(i),y(2:m2),(t(k)+t(k+1))/2)+1/12*ff5(x(i),y(3:m2+1),(t(k)+t(k+1))/2);\n        row2=zeros(m2-1,1);\n        row2(1,1)=5/6+r2;row2(2,1)=1/12-1/2*r2;\n        B=toeplitz(row2);\n        u(i,2:m2,k+1) = chase(B,(H1+H2+dt/2*F2)); \n    end\nend\nF = zeros(m1+1,m2+1,n+1);\nfor i = 1:m1+1\n    for j = 1:m2+1\n        for k = 1:n+1\n            F(i,j,k) = exp(1/2*(x(i)+y(j))-t(k));\n        end\n    end\nend\nerror = abs(F-u);\nfigure(3)\n      \n    mesh(x(2:m1),y(2:m2),error(2:m1,2:m2,n+1))\n    hold on\n  \nMaxErr(ii)=max(max(max(error)));\ndisp(MaxErr(ii));\nend\nfor i=1:3\nord=MaxErr(i)/MaxErr(i+1);\ndisp(['收敛阶为',num2str(ord)]);\nend\n\n    figure(1)\n    mesh(x, y, F(:, :,n+1));\n    figure(2)\n    mesh(x, y, u(:, :, n+1))\n    \n    \n"},{"name":"page267.m","page":267,"code":"for ii=1:4\nxa = 0; xb = 1;\nya = 0; yb = 1;\nta = 0; tb = 1;\nm=10*2^(ii+1);\nn=m;\nh = (xb-xa)/m;\ndt = (tb-ta)/n;\nx = xa:h:xb;  x = x';\ny = ya:h:yb;  y = y';\nt = ta:dt:tb; t = t';\nr = dt/h;\nu = zeros(m+1,m+1,n+1);\nfor i = 1:m+1\n    for j = 1:m+1\n        u(i,j,1)   = exp(1/2*(x(i)+y(j)));\n    end\nend\nff5 = @(x,y,t) 1/2*exp(1/2*(x+y)-t);\nff51 = @(x,y) -exp(1/2*(x+y));\nfor j = 1:m+1\n    for k = 1:n+1\n        u(1,j,k)   = exp(1/2*y(j)-t(k));\n        u(m+1,j,k) = exp(1/2*(1+y(j))-t(k));\n    end\nend\nfor i = 1:m+1\n    for k = 1:n+1\n        u(i,1,k)   = exp(1/2*x(i)-t(k));\n        u(i,m+1,k) = exp(1/2*(1+x(i))-t(k));\n    end\nend\nfor k = 1:n\n    if k == 1\n        u1 = zeros(m+1,m+1);\n        for j = 2:m\n            H1 = zeros(m-1,1);\n            H1(1:m-1) = u(2:m,j,1)+1/2*dt*ff51(x(2:m),y(j))+1/4*dt^2*ff5(x(2:m),y(j),t(1));\n            u1(1,j)   = 1/2*( (u(1,j,1)-1/4*r^2*(u(1,j-1,1)-2*u(1,j,1)+u(1,j+1,1)))+(u(1,j,2)-1/4*r^2*(u(1,j-1,2)-2*u(1,j,2)+u(1,j+1,2))));\n            u1(m+1,j) = 1/2*((u(m+1,j,1)-1/4*r^2*(u(m+1,j-1,1)-2*u(m+1,j,1)+u(m+1,j+1,1)))+(u(m+1,j,2)-1/4*r^2*(u(m+1,j-1,2)-2*u(m+1,j,2)+u(m+1,j+1,2))));\n            H = zeros(m-1,1);\n            H(1,1)   = 1/4*r^2*u1(1,j);\n            H(m-1,1) = 1/4*r^2*u1(m+1,j);\n            row=zeros(m-1,1);\n            row(1,1)=1+1/2*r^2;row(2,1)=-1/4*r^2;\n            A=toeplitz(row);\n            u1(2:m,j) = chase(A,(H1+H));\n        end\n        u12 = zeros(m+1,m+1);\n        for i = 2:m\n            H2= zeros(m-1,1);\n            H2(1:m-1) = u1(i,2:m);\n            u12(i,1)   = 1/2*( u(i,1,1)  +u(i,1,2)  );\n            u12(i,m+1) = 1/2*( u(i,m+1,1)+u(i,m+1,2));\n            H3 = zeros(m-1,1);\n            H3(1,1)   = 1/4*r^2*u12(i,1);\n            H3(m-1,1) = 1/4*r^2*u12(i,m+1);\n            row11=zeros(m-1,1);\n            row11(1,1)=1+1/2*r^2;row11(2,1)=-1/4*r^2;\n            A1=toeplitz(row11);\n            u12(i,2:m) = chase(A1,(H2+H3));\n        end\n        for i = 2:m\n            for j = 2:m\n                u(i,j,2) = 2*u12(i,j)-u(i,j,1);\n            end\n        end\n    else\n        u2 = zeros(m+1,m+1);\n        for j = 2:m\n            H5 = zeros(m-1,1);\n            H5(1:m-1) = u(2:m,j,k)+1/2*dt^2*ff5(x(2:m),y(j),t(k));\n            u2(1,j)   = 1/2*( (u(1,j,k-1)-1/2*r^2*(u(1,j-1,k-1)-2*u(1,j,k-1)+u(1,j+1,k-1)))+(u(1,j,k+1)-1/2*r^2*(u(1,j-1,k+1)-2*u(1,j,k+1)+u(1,j+1,k+1)))   );\n            u2(m+1,j) = 1/2*( (u(m+1,j,k-1)-1/2*r^2*(u(m+1,j-1,k-1)-2*u(m+1,j,k-1)+u(m+1,j+1,k-1)))+(u(m+1,j,k+1)-1/2*r^2*(u(m+1,j-1,k+1)-2*u(m+1,j,k+1)+u(m+1,j+1,k+1)))   );\n            H6 = zeros(m-1,1);\n            H6(1,1)   = 1/2*r^2*u2(1,j);\n            H6(m-1,1) = 1/2*r^2*u2(m+1,j);\n            row0=zeros(m-1,1);\n            row0(1,1)=1+r^2;row0(2,1)=-1/2*r^2;\n            B=toeplitz(row0);\n            u2(2:m,j) =chase(B,(H5+H6));\n        end\n        uu = zeros(m+1,m+1);\n        for i = 2:m\n            HH = zeros(m-1,1);\n            HH(1:m-1) = u2(i,2:m);\n            uu(i,1)   = 1/2*(u(i,1,k-1)+u(i,1,k+1));\n            uu(i,m+1) = 1/2*(u(i,m+1,k-1)+u(i,m+1,k+1));\n            HH1 = zeros(m-1,1);\n            HH1(1,1)   = 1/2*r^2*uu(i,1);\n            HH1(m-1,1) = 1/2*r^2*uu(i,m+1);\n             row1=zeros(m-1,1);\n            row1(1,1)=1+r^2;row1(2,1)=-1/2*r^2;\n            C=toeplitz(row1);\n            uu(i,2:m) = chase(C,(HH+HH1));\n        end\n        for i = 2:m\n            for j = 2:m\n                u(i,j,k+1) = 2*uu(i,j)-u(i,j,k-1);\n            end\n        end\n    end\nend\nF = zeros(m+1,m+1,n+1);\nfor i = 1:m+1\n    for j = 1:m+1\n        for k = 1:n+1\n            F(i,j,k) = exp(1/2*(x(i)+y(j))-t(k));\n        end\n    end\nend\nerror = abs(F-u);\nMaxErr(ii)=max(max(max(error)));\ndisp(MaxErr(ii));\n  figure(3)\n    mesh(x(2:m),y(2:m),error(2:m,2:m,end))\n    hold on\nend\nfor i=1:3\nord=MaxErr(i)/MaxErr(i+1);\ndisp(['收敛阶为',num2str(ord)]);\nend\n    figure(1)\n    mesh(x, y, F(:, :, end));\n    figure(2)\n    mesh(x, y, u(:, :, end))\n  \n"},{"name":"page279.m","page":279,"code":"for ii=1:4\nxa = 0; xb = 1;\nya = 0; yb = 1;\nta = 0; tb = 1;\nm=10*2^(ii-1);\nn=10*4^(ii-1);\nh = (xb-xa)/m;\ndt = (tb-ta)/n;\nx = xa:h:xb;  x = x';\ny = ya:h:yb;  y = y';\nt = ta:dt:tb; t = t';\nr = dt/h;\nu = zeros(m+1,m+1,n+1);\nfor i = 1:m+1\n    for j = 1:m+1\n        u(i,j,1)   = exp(1/2*(x(i)+y(j))); \n    end\nend\nfor j = 1:m+1\n    for k = 1:n+1\n        u(1,j,k)   = exp(1/2*y(j)-t(k));\n        u(m+1,j,k) = exp(1/2*(1+y(j))-t(k)); \n    end\nend\n ff5 = @(x,y,t) 1/2*exp(1/2*(x+y)-t);\nff51 = @(x,y) -exp(1/2*(x+y));\nfor i = 1:m+1\n    for k = 1:n+1\n        u(i,1,k)   = exp(1/2*x(i)-t(k));\n        u(i,m+1,k) = exp(1/2*(1+x(i))-t(k));\n    end\nend\nfor k = 1:n    \n  \n    if k == 1        \n        u1 = zeros(m+1,m+1);\n        \n        for j = 2:m      \n            \n            H1 = zeros(m-1,1);\n            H1(1:m-1) = u(2:m,j,1)+1/2*dt*ff51(x(2:m),y(j))+1/4*dt^2*ff5(x(2:m),y(j),t(1))+...\n1/12*((u(1:m-1,j,1) +1/2*dt*ff51(x(1:m-1),y(j)) +1/4*dt^2*ff5(x(1:m-1),y(j),t(1)) )-2*(u(2:m,j,1)+1/2*dt*ff51(x(2:m),y(j))+ ...\n1/4*dt^2*ff5(x(2:m),y(j),t(1)))+(u(3:m+1,j,1)+1/2*dt*ff51(x(3:m+1),y(j))+1/4*dt^2*ff5(x(3:m+1),y(j),t(1))))+1/12*((u(2:m,j-1,1) +1/2*dt*ff51(x(2:m),y(j-1))+1/4*dt^2*ff5(x(2:m),y(j-1),t(1))-2*(u(2:m,j,1)+ ...\n1/2*dt*ff51(x(2:m),y(j))+1/4*dt^2*ff5(x(2:m),y(j),t(1)))+(u(2:m,j+1,1) +1/2*dt*ff51(x(2:m),y(j+1)) +1/4*dt^2*ff5(x(2:m),y(j+1),t(1)))))+...\n1/144*(((u(1:m-1,j-1,1) +1/2*dt*ff51(x(1:m-1),y(j-1))+1/4*dt^2*ff5(x(1:m-1),y(j-1),t(1)))-2*(u(1:m-1,j,1)+1/2*dt*ff51(x(1:m-1),y(j))+1/4*dt^2*ff5(x(1:m-1),y(j),t(1)))+(u(1:m-1,j+1,1)+ ...\n1/2*dt*ff51(x(1:m-1),y(j+1))+1/4*dt^2*ff5(x(1:m-1),y(j+1),t(1))))-...\n2*((u(2:m,j-1,1)+1/2*dt*ff51(x(2:m),y(j-1))+1/4*dt^2*ff5(x(2:m),y(j-1),t(1)))-2*(u(2:m,j,1)+1/2*dt*ff51(x(2:m),y(j))+1/4*dt^2*ff5(x(2:m),y(j),t(1)))+(u(2:m,j+1,1)+1/2*dt*ff51(x(2:m),y(j+1))+ ...\n1/4*dt^2*ff5(x(2:m),y(j+1),t(1))))+...\n((u(3:m+1,j-1,1) +1/2*dt*ff51(x(3:m+1),y(j-1))+1/4*dt^2*ff5(x(3:m+1),y(j-1),t(1)))-2*(u(3:m+1,j,1)+1/2*dt*ff51(x(3:m+1),y(j))+1/4*dt^2*ff5(x(3:m+1),y(j),t(1)))+(u(3:m+1,j+1,1) +1/2*dt*ff51(x(3:m+1),y(j+1))+ ...\n1/4*dt^2*ff5(x(3:m+1),y(j+1),t(1)))))+...\n1/144*(((u(1:m-1,j-1,1)+1/2*dt*ff51(x(1:m-1),y(j-1))+1/4*dt^2*ff5(x(1:m-1),y(j-1),t(1)))-2*(u(1:m-1,j,1)+1/2*dt*ff51(x(1:m-1),y(j))+1/4*dt^2*ff5(x(1:m-1),y(j),t(1)))...\n+(u(1:m-1,j+1,1) +1/2*dt*ff51(x(1:m-1),y(j+1)) +1/4*dt^2*ff5(x(1:m-1),y(j+1),t(1))))-2*((u(2:m,j-1,1)+1/2*dt*ff51(x(2:m),y(j-1))+1/4*dt^2*ff5(x(2:m),y(j-1),t(1)))-2*(u(2:m,j,1)+ ...\n1/2*dt*ff51(x(2:m),y(j))+1/4*dt^2*ff5(x(2:m),y(j),t(1)))+...\n(u(2:m,j+1,1)+1/2*dt*ff51(x(2:m),y(j+1))+1/4*dt^2*ff5(x(2:m),y(j+1),t(1))))+((u(3:m+1,j-1,1)+1/2*dt*ff51(x(3:m+1),y(j-1))+1/4*dt^2*ff5(x(3:m+1),y(j-1),t(1)))-...\n2*(u(3:m+1,j,1)+1/2*dt*ff51(x(3:m+1),y(j))+1/4*dt^2*ff5(x(3:m+1),y(j),t(1)))+(u(3:m+1,j+1,1)+1/2*dt*ff51(x(3:m+1),y(j+1))+1/4*dt^2*ff5(x(3:m+1),y(j+1),t(1)))));        \n          \n            u1(1,j)= 1/2*((u(1,j,1)+(1/12-1/4*r^2)*(u(1,j-1,1)-2*u(1,j,1)+u(1,j+1,1)))...\n                             +(u(1,j,2)+(1/12-1/4*r^2)*(u(1,j-1,2)-2*u(1,j,2)+u(1,j+1,2))));\n            u1(m+1,j) = 1/2*((u(m+1,j,1)+(1/12-1/4*r^2)*(u(m+1,j-1,1)-2*u(m+1,j,1)+u(m+1,j+1,1)))...\n                             +(u(m+1,j,2)+(1/12-1/4*r^2)*(u(m+1,j-1,2)-2*u(m+1,j,2)+u(m+1,j+1,2))));\n            \n            H2 = zeros(m-1,1);\n            H2(1,1)   = -(1/12-1/4*r^2)*u1(1,j);\n            H2(m-1,1) = -(1/12-1/4*r^2)*u1(m+1,j);\n            row1=zeros(m-1,1);\n            row1(1,1)=5/6+1/2*r^2;row1(2,1)=1/12-1/4*r^2;\n            A=toeplitz(row1);\n            u1(2:m,j) = chase(A,(H1+H2));\n        end\n        \n        uu1 = zeros(m+1,m+1);\n        \n        for i = 2:m            \n            H7= zeros(m-1,1);\n            H7(1:m-1) = u1(i,2:m);\n            \n            uu1(i,1)   = 1/2*(u(i,1,1)+u(i,1,2));\n            uu1(i,m+1) = 1/2*(u(i,m+1,1)+u(i,m+1,2));\n            \n            H8 = zeros(m-1,1);\n            H8(1,1)   = -(1/12-1/4*r^2)*uu1(i,1);\n            H8(m-1,1) = -(1/12-1/4*r^2)*uu1(i,m+1);\n            row2=zeros(m-1,1);\n            row2(1,1)=5/6+1/2*r^2;row2(2,1)=1/12-1/4*r^2;\n            B=toeplitz(row2);\n            uu1(i,2:m) = chase(B,(H7+H8));\n        end\n        \n        for i = 2:m\n            for j = 2:m\n                u(i,j,2) = 2*uu1(i,j)-u(i,j,1);\n            end\n        end\n        \n    else\n   \n        u2 = zeros(m+1,m+1);\n        \n        for j = 2:m\n            H9 = zeros(m-1,1);\n            H9(1:m-1) = u(2:m,j,k)+1/2*dt^2*ff5(x(2:m),y(j),t(k))+...\n1/12*((u(1:m-1,j,k) +1/2*dt^2*ff5(x(1:m-1),y(j),t(k)))-2*(u(2:m,j,k)+1/2*dt^2*ff5(x(2:m),y(j),t(k)))+(u(3:m+1,j,k) +1/2*dt^2*ff5(x(3:m+1),y(j),t(k))))+...\n1/12*((u(2:m,j-1,k) +1/2*dt^2*ff5(x(2:m),y(j-1),t(k)))-2*(u(2:m,j,k)+1/2*dt^2*ff5(x(2:m),y(j),t(k)))+(u(2:m,j+1,k) +1/2*dt^2*ff5(x(2:m),y(j+1),t(k))))+...\n1/144*(((u(1:m-1,j-1,k) +1/2*dt^2*ff5(x(1:m-1),y(j-1),t(k)))-2*(u(1:m-1,j,k)+1/2*dt^2*ff5(x(1:m-1),y(j),t(k)))+(u(1:m-1,j+1,k)+1/2*dt^2*ff5(x(1:m-1),y(j+1),t(k))))-2*((u(2:m,j-1,k)+1/2*dt^2*ff5(x(2:m),y(j-1),t(k)))-...\n2*(u(2:m,j,k)+1/2*dt^2*ff5(x(2:m),y(j),t(k)))+(u(2:m,j+1,k)+1/2*dt^2*ff5(x(2:m),y(j+1),t(k))))+((u(3:m+1,j-1,k)+1/2*dt^2*ff5(x(3:m+1),y(j-1),t(k)))-2*(u(3:m+1,j,k)+1/2*dt^2*ff5(x(3:m+1),y(j),t(k)))+ ...\n(u(3:m+1,j+1,k) +1/2*dt^2*ff5(x(3:m+1),y(j+1),t(k)))));                   \n            u2(1,j)   = 1/2*((u(1,j,k-1)+(1/12-1/2*r^2)*(u(1,j-1,k-1)-2*u(1,j,k-1)+u(1,j+1,k-1)))...\n                             +(u(1,j,k+1)+(1/12-1/2*r^2)*(u(1,j-1,k+1)-2*u(1,j,k+1)+u(1,j+1,k+1))));\n            u2(m+1,j) = 1/2*((u(m+1,j,k-1)+(1/12-1/2*r^2)*(u(m+1,j-1,k-1)-2*u(m+1,j,k-1)+u(m+1,j+1,k-1)))...\n                             +(u(m+1,j,k+1)+(1/12-1/2*r^2)*(u(m+1,j-1,k+1)-2*u(m+1,j,k+1)+u(m+1,j+1,k+1))));\n            \n            H10 = zeros(m-1,1);\n            H10(1,1)   = -(1/12-1/2*r^2)*u2(1,j);\n            H10(m-1,1) = -(1/12-1/2*r^2)*u2(m+1,j);\n            row3=zeros(m-1,1);\n            row3(1,1)=5/6+r^2;row3(2,1)=1/12-1/2*r^2;\n            C=toeplitz(row3);\n            u2(2:m,j) = chase(C,(H10+H9));          \n        end\n        \n        uu2 = zeros(m+1,m+1);\n        \n        for i = 2:m\n            H11 = zeros(m-1,1);\n            H11(1:m-1) = u2(i,2:m);\n            \n            uu2(i,1)   = 1/2*(u(i,1,k-1)+u(i,1,k+1));\n            uu2(i,m+1) = 1/2*(u(i,m+1,k-1)+u(i,m+1,k+1));\n            \n            H12 = zeros(m-1,1);\n            H12(1,1)   = -(1/12-1/2*r^2)*uu2(i,1);\n            H12(m-1,1) = -(1/12-1/2*r^2)*uu2(i,m+1);\n             row4=zeros(m-1,1);\n            row4(1,1)=5/6+r^2;row4(2,1)=1/12-1/2*r^2;\n            D=toeplitz(row4);\n            uu2(i,2:m) = chase(D,(H11+H12));\n        end            \n        \n        for i = 2:m\n            for j = 2:m\n                u(i,j,k+1) = 2*uu2(i,j)-u(i,j,k-1);\n            end\n        end       \n    end\nend\n\nF = zeros(m+1,m+1,n+1);\nfor i = 1:m+1\n    for j = 1:m+1\n        for k = 1:n+1\n            F(i,j,k) = exp(1/2*(x(i)+y(j))-t(k));\n        end\n    end\nend\nerror = abs(F-u);\nMaxErr(ii)=max(max(max(error)));\ndisp(MaxErr(ii));\n  figure(3)\n    mesh(x(2:m),y(2:m),error(2:m,2:m,end))\n    hold on\nend\nfor i=1:3\nord=MaxErr(i)/MaxErr(i+1);\ndisp(['收敛阶为',num2str(ord)]);\nend\n    figure(1)\n    mesh(x, y, F(:, :, end));\n     figure(2)\n    mesh(x, y, u(:, :, end))"},{"name":"untitled.m","page":null,"code":"syms x\ny=(1-x)^3*(5-3*(1-x)^2);\ns=int(y,x,0,1);\nprint(s);\n"},{"name":"untitled123.m","page":null,"code":"for ii=1:4\n    x1 = 0; x2 = 1; y1 = 0; y2 = 1; t1 = 0; t2 = 1; \n    s1 = 0.2;\n    s2=0.1;\n    m1 = (4 * 2^(ii-1));\n    m2 = m1;\n    N = 200;\n    h1 = (x2 - x1) / m1; \n    h2 = h1;\n    dt = (t2 - t1) / N;\n    x = x1:h1:x2; x = x';\n    y = y1:h2:y2; y = y';\n    t = -s1:dt:t2; t = t';\n    n1 = s1 / dt;\n    n2=s2/dt;\n    G = @(x, y, t)-(sqrt(2))/(1 + (2*x + 2*y - sqrt(2)/4*t)^2) + ...\n    (32*(8*x + 8*y - sqrt(2)/4*t))/([1 + (2*x + 2*y - sqrt(2)/4*t)^2]^2) - ...\n    (4*atan(2*x + 2*y - sqrt(2)/4*(t - 0.2)))/((1 + 16*atan(2*x + 2*y - sqrt(2)/4*(t - 0.1))^2)) - ...\n    16*atan(2*x + 2*y - sqrt(2)/4*t)^2;\n    u = zeros(m1+1, m2+1, N+n1+1);\n    for i = 1:m1+1\n        for k=n1+1:n1+N+1\n            u(i, 1, k) =4*atan(2*x(i)-sqrt(2)/4*t(k));\n            u(i, m2+1,k) =4*atan(2*x(i)+2-sqrt(2)/4*t(k));\n        end\n    end\n    for j = 1:m2+1\n        for k=n1+1:n1+N+1\n            u(1, j, k) =4*atan(2*y(j)-sqrt(2)/4*t(k));\n            u(m1+1, j,k) =4*atan(2*y(j)-sqrt(2)/4*t(k));\n        end\n    end\n    for i = 1:m1+1\n        for j = 1:m2+1\n            for k = 1:n1+1\n                u(i, j, k) =4*atan(2*x(i)+2*y(j)-sqrt(2)/4*t(k));\n            end\n        end\n    end\n    a = 2;\n    r1 = a * dt / (h1^2);\n    r2 = a * dt / (h2^2);\n    I = speye(m1-1, m1-1);\n    D = -r2 * I;\n    row2 = zeros(m1-1, 1);\n    row2(1, 1) = 11/6 -2 * (r1 + r2);\n    row2(2, 1) = -r1;\n    C = toeplitz(row2);\n    A = kron(diag(ones(1, m2-2), 1) + diag(ones(1, m2-2), -1), D) + kron(diag(ones(1, m2-1)), C);\n\n    for k = n1+1:N+n1+1\n        H = zeros(m1-1, m2-1);  \n        for i=2:m1-2\n        for j = 2:m2\n            H(i, j-1) = 3*u(i+1, j, k-1) -3/2 * u(i+1, j, k-2) + 1/3 * u(i+1, j, k-3) + ...\n                dt * (G(x(i+1), y(j), t(k)) +(3 * u(i+1, j, k-1) - 3 * u(i+1, j, k-2) + u(i+1, j, k-3))^2 +(u(i+1,j, k-n1)/(1+(u(i+1,j, k-n2))^2)));\n              H(1, j-1) = 3 * u(2, j, k-1) - 3/2 * u(2, j, k-2) + 1/3 * u(2, j, k-3) + r1*u(1,j,k)+...\n                        dt * (G(x(2), y(j), t(k)) +(3 * u(2, j, k-1) - 3 * u(2, j, k-2) + u(2, j, k-3))^2 +(u(2,j, k-n1)/(1+(u(2,j, k-n2))^2)));\n               H(m1-1, j-1) = 3 * u(m1, j, k-1) - 3/2 * u(m1, j, k-2) + 1/3 * u(m1, j, k-3) + r1*u(m1+1,j,k)+...\n                        dt * (G(x(m1), y(j), t(k))+(3 * u(m1, j, k-1) - 3 * u(m1, j, k-2) + u(m1, j, k-3))^2 +(u(m1,j, k-n1)/(1+(u(m1,j, k-n2))^2)));\n        end\n        end\n        H(:, 1) = H(:, 1) - D * u(2:m1, 1, k);\n        H(:, m2-1) = H(:, m2-1) - D * u(2:m1, m2+1, k);  \n        F = reshape(H, (m1-1) * (m2-1), 1);\n        U1 =A\\F;\n        U2=reshape(U1, m1-1, m2-1);\n        u(2:m1, 2:m2, k) = U2;\n    end\n    F = zeros(m1+1, m2+1, N+n1+1);\n    for i = 1:m1+1\n        for j = 1:m2+1\n            for k = 1:N+n1+1\n                F(i, j, k) = 4*atan(2*x(i)+2*y(j)-sqrt(2)/4*t(k));\n            end\n        end\n    end\n\n    error = abs(u - F);\n    MaxErr(ii) = max(max(max(error)));\nend\n\ndisp(MaxErr);\nfor i = 1:3\n    ord(i) = MaxErr(i) / MaxErr(i+1);\nend\n\ndisp(ord);"}],"topics":[{"name":"ADI 与交替方向法","desc":"二维抛物方程的 ADI、Douglas、PR、DY 等交替方向格式，比较精度与稳定性。","files":["ADI.m","ADIexample.m","page236douglas.m","page236DY.m","page236PR.m","page236two.m","page250douglas.m","page250DY.m","page250PR.m"]},{"name":"Crank–Nicolson 与二维隐式格式","desc":"Crank–Nicolson 及二维隐式差分格式的实现。","files":["a253.m","CN.m","untitled123.m"]},{"name":"其他综合实验","desc":"二维问题、追赶法与符号积分等综合实验。","files":["chase.m","page267.m","page279.m","untitled.m"]}]}]};
